"""Command-line interface for the expense tracker."""

from __future__ import annotations

import json
import sqlite3
import sys
from datetime import date
from pathlib import Path
from typing import Any

import click

# Support both ``python -m app.cli`` and the required ``python app/cli.py``.
sys.path.insert(0, str(Path(__file__).resolve().parent.parent))

from app.database import connect
from app.errors import ExpenseTrackerError
from app.models import Budget, Category, Expense, to_cents
from app.repositories import BudgetRepository, CategoryRepository, ExpenseRepository
from app.services import ExpenseService


def _json(value: Any) -> str:
    return json.dumps(value, ensure_ascii=False, sort_keys=True)


def _emit_rows(rows: list[Any]) -> None:
    for row in rows:
        click.echo(_json(row.to_dict()))


def _month(value: str) -> str:
    try:
        parsed = date.fromisoformat(f"{value}-01")
    except ValueError as exc:
        raise click.BadParameter("expected a valid YYYY-MM month") from exc
    if len(value) != 7 or parsed.strftime("%Y-%m") != value:
        raise click.BadParameter("expected a valid YYYY-MM month")
    return value


class ExpenseCLIGroup(click.Group):
    """Turn expected domain and SQLite failures into concise CLI errors."""

    def invoke(self, ctx: click.Context) -> Any:
        try:
            return super().invoke(ctx)
        except (ExpenseTrackerError, ValueError, sqlite3.Error, OSError) as exc:
            raise click.ClickException(str(exc) or exc.__class__.__name__) from exc


@click.group(cls=ExpenseCLIGroup)
@click.option("--db", "database_path", type=click.Path(path_type=Path), default=Path("expenses.db"),
              show_default=True, help="SQLite database file.")
@click.pass_context
def cli(ctx: click.Context, database_path: Path) -> None:
    """Track expenses, categories, and monthly budgets."""
    connection = connect(database_path)
    categories = CategoryRepository(connection)
    expenses = ExpenseRepository(connection)
    budgets = BudgetRepository(connection)
    ctx.ensure_object(dict)
    ctx.obj.update({
        "connection": connection,
        "categories": categories,
        "expenses": expenses,
        "budgets": budgets,
        "service": ExpenseService(expenses, categories, budgets),
    })


@cli.group("expense")
def expense_group() -> None:
    """Create and inspect expenses and expense categories."""


@expense_group.group("category")
def category_group() -> None:
    """Manage expense categories."""


@category_group.command("add")
@click.option("--name", required=True, help="Unique category name.")
@click.option("--description", required=True)
@click.option("--budget", help="Optional default monthly budget in currency units.")
@click.option("--icon")
@click.pass_context
def category_add(ctx: click.Context, name: str, description: str, budget: str | None, icon: str | None) -> None:
    cents = to_cents(budget) if budget is not None else None
    if cents is not None and cents <= 0:
        raise click.ClickException("budget must be greater than zero")
    category = ctx.obj["categories"].create(Category(
        name=name.strip(), description=description, monthly_budget=cents, icon=icon
    ))
    click.echo(_json(category.to_dict()))


@category_group.command("list")
@click.pass_context
def category_list(ctx: click.Context) -> None:
    _emit_rows(ctx.obj["categories"].list_all())


@category_group.command("update")
@click.option("--id", "category_id", type=click.IntRange(min=1), required=True)
@click.option("--name")
@click.option("--description")
@click.option("--budget")
@click.option("--icon")
@click.pass_context
def category_update(
    ctx: click.Context, category_id: int, name: str | None, description: str | None,
    budget: str | None, icon: str | None,
) -> None:
    values: dict[str, Any] = {}
    if name is not None:
        values["name"] = name.strip()
    if description is not None:
        values["description"] = description
