"""Domain models and small value-conversion helpers."""

from __future__ import annotations

from dataclasses import asdict, dataclass
from datetime import date
from decimal import Decimal, InvalidOperation
from typing import Any


def to_cents(value: str | int | float | Decimal) -> int:
    """Convert a decimal currency value to integer cents without float math."""
    try:
        amount = Decimal(str(value))
    except (InvalidOperation, ValueError) as exc:
        raise ValueError(f"invalid monetary amount: {value!r}") from exc
    if not amount.is_finite():
        raise ValueError("monetary amount must be finite")
    cents = amount * 100
    if cents != cents.to_integral_value():
        raise ValueError("monetary amount may have at most two decimal places")
    return int(cents)


def from_cents(cents: int) -> str:
    """Format integer cents as a fixed two-decimal currency string."""
    sign = "-" if cents < 0 else ""
    whole, fraction = divmod(abs(cents), 100)
    return f"{sign}{whole}.{fraction:02d}"


@dataclass(slots=True)
class Category:
    id: int | None = None
    name: str = ""
    description: str = ""
    monthly_budget: int | None = None
    icon: str | None = None

    @property
    def monthly_budget_cents(self) -> int | None:
        return self.monthly_budget

    def to_dict(self) -> dict[str, Any]:
        result = asdict(self)
        result["monthly_budget_cents"] = self.monthly_budget
        result["monthly_budget"] = (
            from_cents(self.monthly_budget) if self.monthly_budget is not None else None
        )
        return result


@dataclass(slots=True)
class Expense:
    id: int | None = None
    amount_cents: int = 0
    description: str = ""
    expense_date: str = ""
    category_id: int = 0
    payment_method: str = "cash"
    is_recurring: bool = False

    @property
    def amount(self) -> str:
        return from_cents(self.amount_cents)

    def to_dict(self) -> dict[str, Any]:
        result = asdict(self)
        result["amount"] = self.amount
        return result


@dataclass(slots=True)
class Budget:
    id: int | None = None
    category_id: int = 0
    month: str = ""
    amount_limit_cents: int = 0

    @property
    def amount(self) -> str:
        return from_cents(self.amount_limit_cents)

    def to_dict(self) -> dict[str, Any]:
        result = asdict(self)
        result["amount"] = self.amount
        return result


def normalize_date(value: str | date) -> str:
    """Return an ISO date string, validating string inputs strictly."""
    if isinstance(value, date):
        return value.isoformat()
    return date.fromisoformat(value).isoformat()
