"""Domain exceptions for the expense tracker."""


class ExpenseTrackerError(Exception):
    """Base exception for expected application errors."""


class CategoryNotFoundError(ExpenseTrackerError):
    """Raised when a requested category does not exist."""


class ExpenseNotFoundError(ExpenseTrackerError):
    """Raised when a requested expense does not exist."""


class BudgetNotFoundError(ExpenseTrackerError):
    """Raised when a requested budget does not exist."""


class BudgetExceededException(ExpenseTrackerError):
    """Raised after an expense causes a category's monthly budget to be exceeded."""

    def __init__(self, message: str, expense: object | None = None) -> None:
        super().__init__(message)
        self.expense = expense


class ValidationError(ExpenseTrackerError):
    """Raised when input data violates a domain rule."""

"""SQLite connection and schema management."""

from __future__ import annotations

import sqlite3
from pathlib import Path


SCHEMA = """
CREATE TABLE IF NOT EXISTS categories (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL UNIQUE,
    description TEXT NOT NULL DEFAULT '',
    monthly_budget INTEGER,
    icon TEXT
);
CREATE TABLE IF NOT EXISTS expenses (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    amount_cents INTEGER NOT NULL CHECK (amount_cents > 0),
    description TEXT NOT NULL,
    expense_date TEXT NOT NULL,
    category_id INTEGER NOT NULL REFERENCES categories(id) ON DELETE RESTRICT,
    payment_method TEXT NOT NULL CHECK (payment_method IN ('cash', 'card', 'transfer')),
    is_recurring INTEGER NOT NULL DEFAULT 0 CHECK (is_recurring IN (0, 1))
);
CREATE INDEX IF NOT EXISTS idx_expenses_date ON expenses(expense_date);
CREATE INDEX IF NOT EXISTS idx_expenses_category ON expenses(category_id);
CREATE TABLE IF NOT EXISTS budgets (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    category_id INTEGER NOT NULL REFERENCES categories(id) ON DELETE CASCADE,
    month TEXT NOT NULL,
    amount_limit_cents INTEGER NOT NULL CHECK (amount_limit_cents > 0),
    UNIQUE(category_id, month)
);
