def connect(database: str | Path | sqlite3.Connection) -> sqlite3.Connection:
    """Open (or configure) a SQLite connection and ensure the schema exists."""
    if isinstance(database, sqlite3.Connection):
        connection = database
    else:
        connection = sqlite3.connect(str(database))
    connection.row_factory = sqlite3.Row
    connection.execute("PRAGMA foreign_keys = ON")
    connection.executescript(SCHEMA)
    connection.commit()
    return connection
    def get_expense_by_id(self, expense_id: int) -> Expense:
        expense = self.expense_repository.get_by_id(expense_id)
        if expense is None:
            raise ExpenseNotFoundError(f"expense {expense_id} was not found")
        return expense

    def add_expense(
        self,
        expense: Expense | Mapping[str, Any] | int,
        description: str | None = None,
        expense_date: date | str | None = None,
        category_id: int | None = None,
        payment_method: str = "cash",
        is_recurring: bool = False,
    ) -> Expense:
        if isinstance(expense, Expense):
            item = expense
        elif isinstance(expense, Mapping):
            values = dict(expense)
            item = Expense(
                amount_cents=values.get("amount_cents", 0),
                description=values.get("description", ""),
                expense_date=normalize_date(values.get("expense_date", date.today())),
                category_id=values.get("category_id", 0),
                payment_method=values.get("payment_method", "cash"),
                is_recurring=bool(values.get("is_recurring", False)),
            )
        else:
            item = Expense(
                amount_cents=expense,
                description=description or "",
                expense_date=normalize_date(expense_date or date.today()),
                category_id=category_id or 0,
                payment_method=payment_method,
                is_recurring=is_recurring,
            )
        try:
            item.expense_date = normalize_date(item.expense_date)
        except (ValueError, TypeError) as exc:
            raise ValidationError(f"invalid expense date: {item.expense_date!r}") from exc
        if item.amount_cents <= 0:
            raise ValidationError("expense amount must be greater than zero")
        if not item.description.strip():
            raise ValidationError("expense description must not be empty")
        if item.payment_method not in PAYMENT_METHODS:
            raise ValidationError("payment method must be cash, card, or transfer")
        if self.category_repository.get_by_id(item.category_id) is None:
            raise CategoryNotFoundError(f"category {item.category_id} was not found")
        created = self.expense_repository.add(item)
        month = created.expense_date[:7]
        if self._category_budget_exceeded(created.category_id, month):
            raise BudgetExceededException(
                f"expense was saved, but category {created.category_id} exceeded its budget for {month}",
                expense=created,
            )
        return created

