    def get_category_spending(
        self, category_id: int, start_date: date | str, end_date: date | str
    ) -> dict[str, Any]:
        if self.category_repository.get_by_id(category_id) is None:
            raise CategoryNotFoundError(f"category {category_id} was not found")
        start, end = normalize_date(start_date), normalize_date(end_date)
        if start > end:
            raise ValidationError("start date must be on or before end date")
        total = self.expense_repository.total_for_category(category_id, start, end)
        return {
            "category_id": category_id,
            "start_date": start,
            "end_date": end,
            "total_cents": total,
            "total": from_cents(total),
            "total_spent_cents": total,
