        }

    def export_to_csv(
        self, file_path: str | Path, start_date: date | str, end_date: date | str
    ) -> int:
        expenses = self.list_expenses(start_date=start_date, end_date=end_date)
        with open(file_path, "w", newline="", encoding="utf-8") as csv_file:
            writer = csv.DictWriter(csv_file, fieldnames=[
                "id", "amount", "amount_cents", "description", "expense_date", "category_id",
                "payment_method", "is_recurring",
            ])
            writer.writeheader()
            for item in expenses:
                writer.writerow(item.to_dict())
        return len(expenses)

    def detect_recurring(self) -> list[Expense]:
        """Mark same-amount/category expenses appearing in consecutive months."""
        grouped: dict[tuple[int, int], dict[str, list[Expense]]] = defaultdict(lambda: defaultdict(list))
        for item in self.expense_repository.list_all():
            month = item.expense_date[:7]
            grouped[(item.category_id, item.amount_cents)][month].append(item)

        marked_ids: set[int] = set()
        for month_map in grouped.values():
            months = sorted(month_map)
            run: list[str] = []
            for current in months:
                if run and current != _next_month(run[-1]):
                    if len(run) >= 2:
                        marked_ids.update(item.id for month in run for item in month_map[month] if item.id is not None)
                    run = []
                run.append(current)
            if len(run) >= 2:
                marked_ids.update(item.id for month in run for item in month_map[month] if item.id is not None)

        self.expense_repository.mark_recurring(sorted(marked_ids))
        return [self.get_expense_by_id(expense_id) for expense_id in sorted(marked_ids)]

