def _category_budget_exceeded(self, category_id: int, month: str) -> bool:
    explicit = self.budget_repository.get_by_category_month(category_id, month)
    if explicit is not None:
        return self.budget_repository.check_exceeded(category_id, month)
    category = self.category_repository.get_by_id(category_id)
    if category is None or category.monthly_budget is None:
        return False
    total = self.expense_repository.monthly_aggregation(month)["categories"]
    spent = next((row["total_cents"] for row in total if row["category_id"] == category_id), 0)
    return spent > category.monthly_budget

def get_monthly_report(self, month: str) -> dict[str, Any]:
    month = _month(month)
    aggregation = self.expense_repository.monthly_aggregation(month)
    breakdown: list[dict[str, Any]] = []
    statuses: list[str] = []
    severity = {"on_track": 0, "warning": 1, "exceeded": 2}
    for row in aggregation["categories"]:
        category_id = row["category_id"]
        budget = self.budget_repository.get_by_category_month(category_id, month)
        category = self.category_repository.get_by_id(category_id)
        limit = budget.amount_limit_cents if budget is not None else (
            category.monthly_budget if category is not None else None
        )
        spent = int(row["total_cents"])
        status = "on_track"
        if limit is not None:
            if spent > limit:
                status = "exceeded"
            elif spent * 100 >= limit * 80:
                status = "warning"
        statuses.append(status)
        breakdown.append({
            "category_id": category_id,
            "category_name": row["category_name"],
            "total_cents": spent,
            "total": from_cents(spent),
            "budget_limit_cents": limit,
            "budget_limit": from_cents(limit) if limit is not None else None,
            "budget_status": status,
        })
    overall = max(statuses, key=severity.get) if statuses else "on_track"
    total_cents = int(aggregation["total_cents"])
    return {
        "month": month,
        "total_cents": total_cents,
        "total": from_cents(total_cents),
        "total_spent_cents": total_cents,
        "total_spent": from_cents(total_cents),
        "categories": breakdown,
        "category_breakdown": breakdown,
        "budget_status": overall,
    }

def get_yearly_summary(self, year: int | str) -> dict[str, Any]:
    try:
        numeric_year = int(year)
        if len(str(year)) != 4 or not 1 <= numeric_year <= 9999:
            raise ValueError
    except (TypeError, ValueError) as exc:
        raise ValidationError(f"invalid year {year!r}; expected YYYY") from exc
    raw = self.expense_repository.yearly_aggregation(numeric_year)
    monthly = {row["month"]: int(row["total_cents"]) for row in raw["monthly_totals"]}
    monthly_totals = [
        {"month": f"{numeric_year:04d}-{month:02d}", "total_cents": monthly.get(f"{month:02d}", 0),
         "total": from_cents(monthly.get(f"{month:02d}", 0))}
        for month in range(1, 13)
    ]
    categories = [
        {"category_id": row["category_id"], "category_name": row["category_name"],
         "total_cents": int(row["total_cents"]), "total": from_cents(int(row["total_cents"]))}
        for row in raw["categories"][:5]
    ]
    yearly_total = sum(monthly.values())
    average = (yearly_total + 6) // 12
    return {
        "year": numeric_year,
        "total_cents": yearly_total,
        "total": from_cents(yearly_total),
        "monthly_totals": monthly_totals,
        "top_categories": categories,
        "top_spending_categories": categories,
        "average_monthly_spend_cents": average,
        "average_monthly_spend": from_cents(average),
    }

