import sqlite3
from typing import List, Optional, Dict, Any
from models import Category, Expense, Budget

class CategoryRepository:
    def __init__(self, conn: sqlite3.Connection):
        self.conn = conn

    def create(self, category: Category) -> Category:
        try:
            cursor = self.conn.execute(
                "INSERT INTO categories (name, description, monthly_budget, icon) VALUES (?, ?, ?, ?)",
                (category.name, category.description, category.monthly_budget, category.icon)
            )
            category.id = cursor.lastrowid
            return category
        except sqlite3.IntegrityError:
            raise ValueError(f"Category conflict: '{category.name}' already exists.")

    def get_by_id(self, category_id: int) -> Optional[Category]:
        cursor = self.conn.execute("SELECT id, name, description, monthly_budget, icon FROM categories WHERE id = ?", (category_id,))
        row = cursor.fetchone()
        if not row: return None
        return Category(id=row[0], name=row[1], description=row[2], monthly_budget=row[3], icon=row[4])

    def list_all(self) -> List[Category]:
        cursor = self.conn.execute("SELECT id, name, description, monthly_budget, icon FROM categories")
        return [Category(id=r[0], name=r[1], description=r[2], monthly_budget=r[3], icon=r[4]) for r in cursor.fetchall()]

    def update(self, category: Category) -> None:
        self.conn.execute(
            "UPDATE categories SET name = ?, description = ?, monthly_budget = ?, icon = ? WHERE id = ?",
            (category.name, category.description, category.monthly_budget, category.icon, category.id)
        )

    def delete(self, category_id: int) -> None:
        self.conn.execute("DELETE FROM categories WHERE id = ?", (category_id,))

    def get_expenses(self, category_id: int) -> List[Expense]:
        cursor = self.conn.execute(
            "SELECT id, amount_cents, description, expense_date, category_id, payment_method, is_recurring FROM expenses WHERE category_id = ?",
            (category_id,)
        )
        return [Expense(id=r[0], amount_cents=r[1], description=r[2], expense_date=r[3], category_id=r[4], payment_method=r[5], is_recurring=bool(r[6])) for r in cursor.fetchall()]


class ExpenseRepository:
    def __init__(self, conn: sqlite3.Connection):
        self.conn = conn

    def create(self, expense: Expense) -> Expense:
        cursor = self.conn.execute(
            "INSERT INTO expenses (amount_cents, description, expense_date, category_id, payment_method, is_recurring) VALUES (?, ?, ?, ?, ?, ?)",
            (expense.amount_cents, expense.description, expense.expense_date, expense.category_id, expense.payment_method, int(expense.is_recurring))
        )
        expense.id = cursor.lastrowid
        return expense

    def get_by_id(self, expense_id: int) -> Optional[Expense]:
        cursor = self.conn.execute("SELECT id, amount_cents, description, expense_date, category_id, payment_method, is_recurring FROM expenses WHERE id = ?", (expense_id,))
        row = cursor.fetchone()
        if not row: return None
        return Expense(id=row[0], amount_cents=row[1], description=row[2], expense_date=row[3], category_id=row[4], payment_method=row[5], is_recurring=bool(row[6]))

    def update(self, expense: Expense) -> None:
        self.conn.execute(
            "UPDATE expenses SET amount_cents = ?, description = ?, expense_date = ?, category_id = ?, payment_method = ?, is_recurring = ? WHERE id = ?",
            (expense.amount_cents, expense.description, expense.expense_date, expense.category_id, expense.payment_method, int(expense.is_recurring), expense.id)
        )

    def delete(self, expense_id: int) -> None:
        self.conn.execute("DELETE FROM expenses WHERE id = ?", (expense_id,))

    def find_filtered(self, category_id: Optional[int] = None, start_date: Optional[str] = None, end_date: Optional[str] = None, payment_method: Optional[str] = None) -> List[Expense]:
        query = "SELECT id, amount_cents, description, expense_date, category_id, payment_method, is_recurring FROM expenses WHERE 1=1"
        params = []
        if category_id is not None:
            query += " AND category_id = ?"
            params.append(category_id)
        if start_date:
            query += " AND expense_date >= ?"
            params.append(start_date)
        if end_date:
            query += " AND expense_date <= ?"
            params.append(end_date)
        if payment_method:
            query += " AND payment_method = ?"
            params.append(payment_method)

        cursor = self.conn.execute(query, params)
        return [Expense(id=r[0], amount_cents=r[1], description=r[2], expense_date=r[3], category_id=r[4], payment_method=r[5], is_recurring=bool(r[6])) for r in cursor.fetchall()]

    def get_aggregation(self, month_or_year: str) -> List[Dict[str, Any]]:
        query = """
            SELECT category_id, SUM(amount_cents) as total 
            FROM expenses 
            WHERE strftime(?, expense_date) = ? 
            GROUP BY category_id
        """
        fmt = "%Y-%m" if len(month_or_year) == 7 else "%Y"
        cursor = self.conn.execute(query, (fmt, month_or_year))
        return [{"category_id": r[0], "total_cents": r[1]} for r in cursor.fetchall()]


class BudgetRepository:
    def __init__(self, conn: sqlite3.Connection):
        self.conn = conn

    def create_or_update(self, budget: Budget) -> Budget:
        cursor = self.conn.execute(
            """INSERT INTO budgets (category_id, month, amount_limit_cents) VALUES (?, ?, ?)
               ON CONFLICT(category_id, month) DO UPDATE SET amount_limit_cents = excluded.amount_limit_cents""",
            (budget.category_id, budget.month, budget.amount_limit_cents)
        )
        if not budget.id:
            budget.id = cursor.lastrowid
        return budget

    def list_all(self, category_id: Optional[int] = None, month: Optional[str] = None) -> List[Budget]:
        query = "SELECT id, category_id, month, amount_limit_cents FROM budgets WHERE 1=1"
        params = []
        if category_id is not None:
            query += " AND category_id = ?"
            params.append(category_id)
        if month:
            query += " AND month = ?"
            params.append(month)
        cursor = self.conn.execute(query, params)
        return [Budget(id=r[0], category_id=r[1], month=r[2], amount_limit_cents=r[3]) for r in cursor.fetchall()]

    def delete(self, category_id: int, month: str) -> None:
        self.conn.execute("DELETE FROM budgets WHERE category_id = ? AND month = ?", (category_id, month))

    def get_budget(self, category_id: int, month: str) -> Optional[Budget]:
        cursor = self.conn.execute("SELECT id, category_id, month, amount_limit_cents FROM budgets WHERE category_id = ? AND month = ?", (category_id, month))
        row = cursor.fetchone()
        if not row: return None
        return Budget(id=row[0], category_id=row[1], month=row[2], amount_limit_cents=row[3])

    def get_total_spent_for_month(self, category_id: int, month: str) -> int:
        cursor = self.conn.execute(
            "SELECT SUM(amount_cents) FROM expenses WHERE category_id = ? AND strftime('%Y-%m', expense_date) = ?",
            (category_id, month)
        )
        row = cursor.fetchone()
        return row[0] if row[0] is not None else 0
