import csv
import sqlite3
from typing import List, Optional, Dict, Any
from models import Category, Expense, Budget
from exceptions import CategoryNotFoundError, ExpenseNotFoundError, BudgetExceededException
from repositories import CategoryRepository, ExpenseRepository, BudgetRepository

class ExpenseService:
    def __init__(self, conn: sqlite3.Connection):
        self.conn = conn
        self.category_repo = CategoryRepository(conn)
        self.expense_repo = ExpenseRepository(conn)
        self.budget_repo = BudgetRepository(conn)

    def list_expenses(self, category_id: Optional[int] = None, start_date: Optional[str] = None, end_date: Optional[str] = None, payment_method: Optional[str] = None) -> List[Expense]:
        return self.expense_repo.find_filtered(category_id, start_date, end_date, payment_method)

    def get_expense_by_id(self, expense_id: int) -> Expense:
        expense = self.expense_repo.get_by_id(expense_id)
        if not expense: raise ExpenseNotFoundError(f"Expense {expense_id} not found.")
        return expense

    def add_expense(self, expense: Expense) -> Expense:
        with self.conn:
            if not self.category_repo.get_by_id(expense.category_id):
                raise CategoryNotFoundError(f"Category {expense.category_id} does not exist.")

            created_expense = self.expense_repo.create(expense)

            month = expense.expense_date[:7]
            budget = self.budget_repo.get_budget(expense.category_id, month)
            if budget:
                total_spent = self.budget_repo.get_total_spent_for_month(expense.category_id, month)
                if total_spent > budget.amount_limit_cents:
                    raise BudgetExceededException(
                        f"Budget limit exceeded for category {expense.category_id} in {month}!",
                        total_spent - budget.amount_limit_cents
                    )
            return created_expense

    def update_expense(self, expense_id: int, data: Dict[str, Any]) -> Expense:
        with self.conn:
            expense = self.get_expense_by_id(expense_id)
            for key, val in data.items():
                if val is not None:
                    setattr(expense, key, val)
            self.expense_repo.update(expense)
            return expense

    def delete_expense(self, expense_id: int) -> None:
        with self.conn:
            self.get_expense_by_id(expense_id)
            self.expense_repo.delete(expense_id)

    def get_monthly_report(self, month: str) -> Dict[str, Any]:
        expenses = self.expense_repo.find_filtered(start_date=f"{month}-01", end_date=f"{month}-31")
        total_spent = sum(e.amount_cents for e in expenses)

        breakdown = {}
        for e in expenses:
            breakdown[e.category_id] = breakdown.get(e.category_id, 0) + e.amount_cents

        categories_status = {}
        for cat_id, spent in breakdown.items():
            budget = self.budget_repo.get_budget(cat_id, month)
            if not budget:
                status = "on_track"
            elif spent > budget.amount_limit_cents:
                status = "exceeded"
            elif spent >= (budget.amount_limit_cents * 0.9):
                status = "warning"
            else:
                status = "on_track"
            categories_status[cat_id] = {"spent": spent, "status": status}

        return {"total_spent": total_spent, "breakdown": categories_status}

    def get_yearly_summary(self, year: str) -> Dict[str, Any]:
        expenses = self.expense_repo.find_filtered(start_date=f"{year}-01-01", end_date=f"{year}-12-31")
        if not expenses:
            return {"monthly_totals": {}, "top_categories": [], "monthly_average": 0.0}

        monthly_totals = {}
        category_totals = {}
        for e in expenses:
            m = e.expense_date[:7]
            monthly_totals[m] = monthly_totals.get(m, 0) + e.amount_cents
            category_totals[e.category_id] = category_totals.get(e.category_id, 0) + e.amount_cents

        sorted_cats = sorted(category_totals.items(), key=lambda x: x[1], reverse=True)
        avg_spend = sum(monthly_totals.values()) / 12.0

        return {"monthly_totals": monthly_totals, "top_categories": sorted_cats[:3], "monthly_average": avg_spend}

    def get_category_spending(self, category_id: int, start_date: str, end_date: str) -> int:
        expenses = self.expense_repo.find_filtered(category_id=category_id, start_date=start_date, end_date=end_date)
        return sum(e.amount_cents for e in expenses)

    def export_to_csv(self, file_path: str, start_date: Optional[str] = None, end_date: Optional[str] = None) -> None:
        expenses = self.expense_repo.find_filtered(start_date=start_date, end_date=end_date)
        with open(file_path, mode='w', newline='', encoding='utf-8') as f:
            writer = csv.writer(f)
            writer.writerow(["ID", "Amount (Cents)", "Description", "Date", "Category ID", "Payment Method", "Recurring"])
            for e in expenses:
                writer.writerow([e.id, e.amount_cents, e.description, e.expense_date, e.category_id, e.payment_method, int(e.is_recurring)])

    def detect_recurring(self) -> int:
        with self.conn:
            expenses = self.expense_repo.find_filtered()
            signature_map = {}
            for e in expenses:
                sig = (e.amount_cents, e.category_id, e.description)
                signature_map.setdefault(sig, []).append(e)

            marked_count = 0
            for sig, item_list in signature_map.items():
                if len(item_list) >= 2:
                    for e in item_list:
                        if not e.is_recurring:
                            e.is_recurring = True
                            self.expense_repo.update(e)
                            marked_count += 1
            return marked_count

