from .cli import main

if __name__ == "__main__":
    main()
"""Click command-line interface for expense and category management."""

import sqlite3
from datetime import date
from decimal import Decimal, InvalidOperation
from pathlib import Path
from typing import Any

import click

from .database import Database
from .exceptions import BudgetExceededException, ExpenseTrackerError
from .models import Budget, Category
from .service import ExpenseService


class SafeGroup(click.Group):
    """Convert expected domain and validation errors into readable CLI errors."""

    def invoke(self, ctx: click.Context) -> Any:
        try:
            return super().invoke(ctx)
        except (ExpenseTrackerError, ValueError, sqlite3.IntegrityError) as error:
            raise click.ClickException(str(error)) from error


def dollars_to_cents(value: str) -> int:
    try:
        amount = Decimal(value)
    except InvalidOperation as error:
        raise click.BadParameter("must be a monetary amount, such as 12.50") from error
    if not amount.is_finite() or amount < 0:
        raise click.BadParameter("must be a finite, non-negative amount")
    cents = amount * 100
    if cents != cents.to_integral_value():
        raise click.BadParameter("must have no more than two decimal places")
    return int(cents)


def cents_to_dollars(cents: int) -> str:
    return f"${Decimal(cents) / Decimal(100):.2f}"


def _init_context(ctx: click.Context, db_path: str) -> None:
    database = Database(db_path)
    ctx.ensure_object(dict)
    ctx.obj["database"] = database
    ctx.obj["service"] = ExpenseService(database)
    ctx.call_on_close(database.close)


def _date_option(value: str | None) -> date | None:
    if value is None:
        return None
    try:
        return date.fromisoformat(value)
    except ValueError as error:
        raise click.BadParameter("must use YYYY-MM-DD format") from error


@click.group(cls=SafeGroup, invoke_without_command=False)
@click.option("--db", "db_path", envvar="EXPENSE_DB_PATH", default="expenses.db", show_default=True,
              help="SQLite database file.")
@click.pass_context
def expense(ctx: click.Context, db_path: str) -> None:
    """Track expenses, categories, reports, and CSV exports."""
    _init_context(ctx, db_path)


@expense.group(cls=SafeGroup)
@click.pass_context
def category(ctx: click.Context) -> None:
    """Manage expense categories."""


@category.command("add")
@click.option("--name", required=True)
@click.option("--description", required=True)
@click.option("--budget", type=str, help="Optional monthly budget in dollars.")
@click.option("--icon", type=str)
@recurring.command("detect")
@click.pass_context
def recurring_detect(ctx: click.Context) -> None:
    detected = ctx.obj["service"].detect_recurring()
    click.echo(f"Marked {len(detected)} expense(s) as recurring.")


@click.group(cls=SafeGroup)
@click.option("--db", "db_path", envvar="EXPENSE_DB_PATH", default="expenses.db", show_default=True,
              help="SQLite database file.")
@click.pass_context
def budget_cli(ctx: click.Context, db_path: str) -> None:
    """Manage monthly category budgets."""
    _init_context(ctx, db_path)


@budget_cli.command("list")
@click.option("--category", "category_id", type=int)
@click.option("--month")
@click.pass_context
def budget_list(ctx: click.Context, category_id: int | None, month: str | None) -> None:
    budgets = ctx.obj["service"].budgets.list_all(category_id, month)
    if not budgets:
        click.echo("No budgets.")
        return
    for item in budgets:
        click.echo(f"{item.id}\tcategory={item.category_id}\t{item.month}\t{cents_to_dollars(item.amount_limit_cents)}")


@budget_cli.command("add")
@click.option("--category-id", type=int, required=True)
@click.option("--month", required=True)
@click.option("--amount", required=True, help="Budget amount in dollars.")
@click.pass_context
def budget_add(ctx: click.Context, category_id: int, month: str, amount: str) -> None:
    service: ExpenseService = ctx.obj["service"]
    service.categories.get_by_id(category_id)
    saved = service.budgets.create(Budget(category_id=category_id, month=month,
                                          amount_limit_cents=dollars_to_cents(amount)))
    click.echo(f"Created budget {saved.id} for category {category_id} in {month}")


@budget_cli.command("update")
@click.option("--category-id", type=int, required=True)
@click.option("--month", required=True)
@click.option("--amount", help="New budget amount in dollars.")
@click.pass_context
def budget_update(ctx: click.Context, category_id: int, month: str, amount: str | None) -> None:
    if amount is None:
        raise click.UsageError("--amount is required")
    saved = ctx.obj["service"].budgets.update(category_id, month, dollars_to_cents(amount))
    click.echo(f"Updated budget {saved.id}: {cents_to_dollars(saved.amount_limit_cents)}")


@budget_cli.command("delete")
@click.option("--category-id", type=int, required=True)
@click.option("--month", required=True)
@click.pass_context
def budget_delete(ctx: click.Context, category_id: int, month: str) -> None:
    ctx.obj["service"].budgets.delete(category_id, month)
    click.echo(f"Deleted budget for category {category_id} in {month}")


def main() -> None:
    expense(prog_name="expense")


def budget_main() -> None:
    budget_cli(prog_name="budget")
