"""Library use cases and transaction-safe borrowing/returning operations."""

from __future__ import annotations

from datetime import date, timedelta

from .database import Database
from .errors import AlreadyReturnedLoanError, BookNotAvailableError, InactiveMemberError
from .models import Author, Book, Loan, Member
from .repositories import AuthorRepository, BookRepository, LoanRepository, MemberRepository


class LibraryService:
    def __init__(self, database: Database) -> None:
        self.database = database
        self.books = BookRepository(database)
        self.authors = AuthorRepository(database)
        self.members = MemberRepository(database)
        self.loans = LoanRepository(database)

    def add_author(self, author: Author) -> Author:
        return self.authors.create(author)

    def add_book(self, book: Book) -> Book:
        return self.books.create(book)

    def add_member(self, member: Member) -> Member:
        return self.members.create(member)

    def borrow_book(self, member_id: int, book_id: int, today: date | None = None) -> Loan:
        loan_date = today or date.today()
        due_date = loan_date + timedelta(days=14)
        with self.database.transaction() as connection:
            member = self.members.get(member_id, connection)
            if not member.is_active:
                raise InactiveMemberError(f"Member {member_id} is inactive")
            book = self.books.get(book_id, connection)
            if book.available_copies <= 0:
                raise BookNotAvailableError(f"Book {book_id} has no available copies")
            updated_book = Book(
                id=book.id, title=book.title, isbn=book.isbn, author_id=book.author_id,
                published_year=book.published_year, available_copies=book.available_copies - 1,
            )
            self.books.update(updated_book, connection)
            return self.loans.create(
                Loan(book_id=book_id, member_id=member_id, loan_date=loan_date, due_date=due_date), connection
            )

    def return_book(self, loan_id: int, today: date | None = None) -> Loan:
        return_date = today or date.today()
        with self.database.transaction() as connection:
            loan = self.loans.get(loan_id, connection, today=return_date)
            if loan.return_date is not None or loan.status == "returned":
                raise AlreadyReturnedLoanError(f"Loan {loan_id} has already been returned")
            updated_loan = Loan(
                id=loan.id, book_id=loan.book_id, member_id=loan.member_id,
                loan_date=loan.loan_date, due_date=loan.due_date,
                return_date=return_date, status="returned",
            )
            result = self.loans.update(updated_loan, connection)
            book = self.books.get(loan.book_id, connection)
            updated_book = Book(
                id=book.id, title=book.title, isbn=book.isbn, author_id=book.author_id,
                published_year=book.published_year, available_copies=book.available_copies + 1,
            )
            self.books.update(updated_book, connection)
            return result

    def get_overdue_loans(self, today: date | None = None) -> list[Loan]:
        return self.loans.find_overdue(today=today)

    def renew_membership(self, member_id: int) -> Member:
        with self.database.transaction() as connection:
            member = self.members.get(member_id, connection)
            member.is_active = not member.is_active
            return self.members.update(member, connection)

    def search_books(self, query: str) -> list[Book]:
        return self.books.search(query)
"""Errors raised by the library domain and persistence layers."""


class LibraryError(Exception):
    """Base class for expected library errors."""


class NotFoundError(LibraryError):
    """Raised when a requested record does not exist."""

    def __init__(self, entity: str, record_id: int) -> None:
        self.entity = entity
        self.record_id = record_id
        super().__init__(f"{entity} {record_id} was not found")


class ValidationError(LibraryError):
    """Raised when a domain value is invalid."""


class BookNotAvailableError(LibraryError):
    """Raised when borrowing a book with no available copies."""


class InactiveMemberError(LibraryError):
    """Raised when an inactive member attempts to borrow a book."""


class AlreadyReturnedLoanError(LibraryError):
    """Raised when a loan is returned more than once."""


class DuplicateRecordError(LibraryError):
    """Raised when a unique field conflicts with an existing record."""


ERROR_TYPES = (
    LibraryError,
    NotFoundError,
    ValidationError,
    BookNotAvailableError,
    InactiveMemberError,
    AlreadyReturnedLoanError,
    DuplicateRecordError,
)

__all__ = ["ERROR_TYPES", *(error.__name__ for error in ERROR_TYPES)]

