"""Mechanical persistence mappings derived from the data model.

The entity set and primary keys are already fixed by steps B and D.  Table
names and ordinary indexes do not need a model call: they follow directly from
the entity name, the declared fields and the foreign keys.  The model still
owns custom repository methods; this module only supplies the mapping side of
step H.
"""

from __future__ import annotations

import re

_FILTER_FIELDS = frozenset({"month", "payment_method", "status", "is_recurring"})


def _snake(name):
    first = re.sub(r"(.)([A-Z][a-z]+)", r"\1_\2", str(name))
    return re.sub(r"([a-z0-9])([A-Z])", r"\1_\2", first).lower()


def table_name(entity):
    """A conventional plural snake-case table name."""
    stem = _snake(entity)
    if not stem:
        return "records"
    if stem.endswith(("s", "x", "z", "ch", "sh")):
        return stem + "es"
    if stem.endswith("y") and len(stem) > 1 and stem[-2] not in "aeiou":
        return stem[:-1] + "ies"
    return stem + "s"


def _fields(model):
    return [
        field for field in (model.get("fields") or ())
        if isinstance(field, dict) and isinstance(field.get("name"), str)
    ]


def _primary_key(fields):
    for field in fields:
        if field.get("primary_key") and field.get("name"):
            return field["name"]
    return "id"


def _indexes(fields):
    indexes = []
    for field in fields:
        name = field.get("name")
        if not name or name == _primary_key(fields):
            continue
        kind = str(field.get("type") or "").strip().lower()
        if (field.get("unique") or field.get("foreign_key")
                or kind in {"date", "datetime", "timestamp"}
                or name in _FILTER_FIELDS):
            indexes.append(name)
    return indexes


def entity_mappings(data_models, entities):
    """One mapping per persisted entity, in the supplied order."""
    by_name = {
        model.get("name"): model
        for model in (data_models or ())
        if isinstance(model, dict) and isinstance(model.get("name"), str)
    }
    mappings = []
    for entity in entities or ():
        model = by_name.get(entity, {})
        fields = _fields(model)
        mappings.append({
            "entity": entity,
            "table": table_name(entity),
            "primary_key": _primary_key(fields),
            "indexes": _indexes(fields),
        })
    return mappings

content.text:
    The entities step D declared CRUD operations for are the persisted ones. If
    step D named none, every modelled entity is persisted — better a repository
    too many than a missing mapping.
    """
    primary_keys = vocabulary.primary_key_of
    names = vocabulary.crud_entities or vocabulary.entity_names
    return tuple((name, primary_keys.get(name)) for name in names)


def fixed_sequence(prefix, count):
    """A JSON array emitting exactly `prefix-0 … prefix-(count-1)` in order."""
    parts = ['"[" ws', f"{prefix}-0"]
    for index in range(1, count):
        parts.append(f'ws "," ws {prefix}-{index}')
    parts.append('ws "]"')
    return " ".join(parts)

def repository_methods(vocabulary):
    """Step H grammar for the custom-method pass: repositories only.

    The mappings are generated by `mappings.entity_mappings`, so the model does
    not spend tokens on table names or indexes and cannot contradict them.
    """
    entries = persisted_entities(vocabulary)
    if not entries:
        return grammar_open.persistence_ports()
    repository_rules = []
    for index, (entity, _primary_key) in enumerate(entries):
        repository_rules.append(
            rule(
                f"repo-{index}",
                json_object(
                    [
                        ("entity", json_literal(entity)),
                        ("interface_name", "identifier"),
                        ("methods", "method-list"),
                    ]
                ),
            )
        )
    return grammar(
        [
            rule("root", json_object([("persistence_ports", "ports-object")])),
            rule("ports-object", json_object([("repositories", "repository-list")])),
            rule("repository-list", fixed_sequence("repo", len(entries))),
            *repository_rules,
            *grammar_open.method_rules(minimum=0),
        ]
    )

