def plan_method(method, entry, entity_names=()):
    """Return `(strategy, detail)` for one contract method.

    `method` is the service_contracts/persistence_ports method object, `entry`
    its pattern_matches entry or None when step F never saw it. Detail is the
    CRUD kind, the rule id, or the stub reason — everything the emitter needs,
    nothing it must re-derive.
    """
    method = method if isinstance(method, dict) else {}
    name = method.get("name") if isinstance(method.get("name"), str) else ""
    if entry is not None:
        kind, payload = tie_rules.effective_directive(entry)
        if kind == "pattern":
            crud = classify_crud(name)
            if crud == "filter" and not _has_params(method):
                # A filter with no parameters filters nothing: `find_active`
                # with no status argument emitted a body returning every
                # record, silently dropping the constraint the name states.
                return ("stub", f"pattern {payload}: filter with no parameters filters nothing")
            if payload == "READ_ONE_BY_ID":
                # One record by its key: scalar parameters and an entity
                # return are the whole claim, whatever the method is called.
                if _shape_crud(method, entity_names) == "read_one":
                    return ("crud:read_one", payload)
                return ("stub", "pattern READ_ONE_BY_ID: needs scalar key "
                                "parameters and an entity return")
            if payload in MECHANICAL_PATTERNS and crud is not None:
                return (f"crud:{crud}", payload)
            if payload in ("FILTER_BY_FIELD", "FILTER_WITH_PAGINATION"):
                # Both patterns describe a filtered read; when the signature
                # is exactly that (list return, scalar-only parameters) the
                # filter body is the whole method. Pagination parameters
                # (limit, offset, order_by) match no field and the emitter
                # refuses those bodies loudly, so nothing is dropped here.
                shape = _filter_by_shape(method, entity_names)
                if shape is not None:
                    return (f"crud:{shape}", f"{payload}: by parameter shape")
            # Non-CRUD mechanical patterns: each has a fixed signature the
            # catalog enforces, so the emitter can write it without the LLM.
            if payload == "AGGREGATE_BY_FK_AND_DATE":
                if _shape_aggregate(method, entity_names):
                    return ("aggregate:fk_date", payload)
            if payload == "AGGREGATE_BY_FK":
                if _shape_aggregate(method, entity_names):
                    return ("aggregate:fk", payload)
            if payload == "COUNT_ACTIVE_BY_FK":
                if _shape_count_active(method, entity_names):
                    return ("count_active", payload)
            if payload == "FILTER_WITH_PAGINATION":
                shape = _filter_by_shape(method, entity_names)
                if shape is not None:
                    return (f"crud:{shape}", f"{payload}: by parameter shape")
            if payload == "EXISTS_BY_UNIQUE_COMPOSITE":
                if _shape_exists_unique(method, entity_names):
                    return ("exists_unique", payload)
            if payload == "THRESHOLD_SCAN":
                if _shape_threshold(method, entity_names):
                    return ("threshold", payload)
            if payload == "BUDGET_OVERFLOW_GUARD":
                if _shape_budget_guard(method, entity_names):
                    return ("budget_guard", payload)
            if payload == "QUOTA_CAPACITY_GUARD":
                if _shape_quota_guard(method, entity_names):
                    return ("quota_guard", payload)
            if payload == "STOCK_SUFFICIENCY_GUARD":
                if _shape_stock_guard(method, entity_names):
                    return ("stock_guard", payload)
            if payload == "PRICE_MARGIN_GUARD":
                if _shape_price_guard(method, entity_names):
                    return ("price_guard", payload)
            if payload == "STATE_TRANSITION_GUARD":
                if _shape_state_guard(method, entity_names):
                    return ("state_guard", payload)
            return ("stub", f"pattern {payload}: no mechanical reading")
        if kind == "rule":
            crud = classify_crud(name)
            if crud == "filter" and not _has_params(method):
                return ("stub", f"rule {payload}: filter with no parameters filters nothing")
            if crud is not None:
                return (f"crud:{crud}", payload)
            return ("stub", f"rule {payload}: method needs custom logic")
        if kind == "llm-gap":
            # A refused claim is about the claim, not the signature: a gap
            # refusing AGGREGATE for an entity return still reads as the
