def repair_flat_prose_surface(components, services, requirements, log=None):
    """Turn the split path's flat action names into backed leaf commands.

    A prose-only prompt (no backticked command lines) leaves the components
    splitter with action names such as ``add_customer``.  Asked for one group,
    the model tends to repeat every action as a subcommand of every group, so
    the merged surface becomes a Cartesian product no service can back.  When
    the requirements name no command lines, the generated commands are allowed
    to be whatever words the service contract uses: flatten each command to a
    leaf whose name is the service method it will call, and give it that
    method's parameters as flags.  Explicit command lines never take this path.
    """
    from kernel.extraction import command_lines

    if not isinstance(components, dict) or not isinstance(services, list):
        return components
    if command_lines.extract_command_lines(requirements or ""):
        return components
    facade = components.get("facade")
    if not isinstance(facade, dict) or (facade.get("type") or "").lower() != "cli":
        return components
    invocation = facade.get("invocation")
    commands = invocation.get("commands") if isinstance(invocation, dict) else None
    if not isinstance(commands, list) or not commands:
        return components

    methods = []
    for service in services:
        if not isinstance(service, dict):
            continue
        for method in service.get("methods") or []:
            if isinstance(method, dict) and isinstance(method.get("name"), str):
                methods.append(method)
    if not methods:
        return components

    type_names = {
        "int": "int", "integer": "int", "bool": "bool", "boolean": "bool",
        "float": "float", "double": "float", "decimal": "float",
        "money": "float", "str": "str", "string": "str", "text": "str",
        "datetime": "str", "date": "str", "list": "str", "dict": "str",
    }

    def method_for(name):
        tokens = [token for token in re.split(r"[^a-z0-9]+", name.lower())
                  if token]
        if not tokens:
            return None
        verb = tokens[0]
        nouns = tokens[1:]
        family = set(surface_checks.COMMAND_VERB_STEMS.get(verb, (verb,)))
        exact = [method for method in methods
                 if normalize(method["name"]) == normalize(name)]
        if exact:
            return exact[0]
        scored = []
        for method in methods:
            flat = normalize(method["name"])
            if nouns and not all(noun in flat for noun in nouns):
                continue
            if not any(stem in flat for stem in family):
                continue
            scored.append((len(method["name"]), method))
        scored.sort(key=lambda item: item[0])
        return scored[0][1] if scored else None

    def options_for(method, name, previous):
        params = [param for param in method.get("params") or []
                  if isinstance(param, dict) and param.get("name")]
        if not params:
            return []
        optional_verb = name.startswith(("search", "list", "read", "update"))
        options = []
        for index, param in enumerate(params):
            raw = param["name"]
            flag = "--" + raw.replace("_", "-")
            declared = str(param.get("type") or "").strip().lower()
            required = (not optional_verb and index == 0) or (
                not optional_verb and method["name"].startswith(
                    ("add", "create", "delete", "confirm", "cancel", "ship")))
            prior = next((option for option in previous
                          if option_dest(option) == raw), None)
            if prior is not None:
                required = bool(prior.get("required"))
            options.append({
                "name": flag,
                "short": None,
                "type": type_names.get(declared, "str"),
                "required": required,
                "default": None,
            })
        return options

    repaired = []
    seen = set()
    for command in commands:
        if not isinstance(command, dict) or not isinstance(command.get("name"), str):
            continue
        name = command["name"]
        previous = []
        for sub in command.get("subcommands") or []:
            if isinstance(sub, dict) and sub.get("name") == name:
                previous = [option for option in sub.get("options") or []
                            if isinstance(option, dict)]
                break
        method = method_for(name)
        if method is None:
            if log is not None:
                log.write(
                    f"[!] step adapters: flat surface command '{name}' has no "
                    "service method — dropped rather than left unbacked")
            continue
        target = method["name"]
        if normalize(target) in seen:
            continue
        seen.add(normalize(target))
        repaired.append({
            "name": target,
            "options": options_for(method, name, previous),
            "subcommands": [],
        })
        if target != name and log is not None:
            log.write(
                f"[ok] step adapters: flat surface command '{name}' -> "
                f"'{target}' (service method)")
    if repaired:
        invocation["commands"] = repaired
        if log is not None:
            log.write(
                f"[ok] step adapters: flattened prose-derived surface to "
                f"{len(repaired)} backed command(s)")
    return components


