        return Product(id=row["id"], sku=row["sku"], name=row["name"],
                       category_id=row["category_id"], price_cents=row["price_cents"],
                       stock_qty=row["stock_qty"], low_active=bool(row["low_active"]))

    def create(self, product: Product) -> Product:
        with self.database._lock:
            cursor = self.database.connection.execute(
                """INSERT INTO products (sku, name, category_id, price_cents, stock_qty, low_active)
                   VALUES (?, ?, ?, ?, ?, ?)""",
                (product.sku, product.name, product.category_id, product.price_cents,
                 product.stock_qty, int(product.low_active)),
            )
            self.database.connection.commit()
            return self.get_by_id(int(cursor.lastrowid))

    def get_by_id(self, product_id: int) -> Product | None:
        row = self.database.connection.execute(
            "SELECT * FROM products WHERE id = ?", (product_id,)
        ).fetchone()
        return self._from_row(row) if row else None

    def find_by_sku(self, sku: str) -> Product | None:
        row = self.database.connection.execute(
            "SELECT * FROM products WHERE sku = ?", (sku,)
        ).fetchone()
        return self._from_row(row) if row else None

    def list_all(self) -> list[Product]:
        rows = self.database.connection.execute("SELECT * FROM products ORDER BY id").fetchall()
        return [self._from_row(row) for row in rows]

    def update(self, product_id: int, data: dict[str, object]) -> Product | None:
        allowed = {"sku", "name", "category_id", "price_cents", "stock_qty", "low_active"}
        updates = {key: value for key, value in data.items() if key in allowed}
        if "low_active" in updates:
            updates["low_active"] = int(bool(updates["low_active"]))
        if not updates:
            return self.get_by_id(product_id)
        assignments = ", ".join(f"{key} = ?" for key in updates)
        with self.database._lock:
            cursor = self.database.connection.execute(
                f"UPDATE products SET {assignments} WHERE id = ?",
                (*updates.values(), product_id),
            )
            self.database.connection.commit()
        return self.get_by_id(product_id) if cursor.rowcount else None

    def delete(self, product_id: int) -> bool:
        with self.database._lock:
            cursor = self.database.connection.execute("DELETE FROM products WHERE id = ?", (product_id,))
            self.database.connection.commit()
            return cursor.rowcount > 0

    def find_by_category(self, category_id: int) -> list[Product]:
        rows = self.database.connection.execute(
            "SELECT * FROM products WHERE category_id = ? ORDER BY id", (category_id,)
        ).fetchall()
        return [self._from_row(row) for row in rows]

    def find_low_stock(self) -> list[Product]:
        rows = self.database.connection.execute(
            """SELECT p.* FROM products AS p
               JOIN categories AS c ON c.id = p.category_id
               WHERE c.reorder_threshold IS NOT NULL AND p.stock_qty < c.reorder_threshold
               ORDER BY p.id"""
        ).fetchall()
        return [self._from_row(row) for row in rows]

    def stock_value_by_category(self) -> list[dict[str, int | str]]:
        rows = self.database.connection.execute(
            """SELECT c.id AS category_id, c.name AS category_name,
                      COALESCE(SUM(p.price_cents * p.stock_qty), 0) AS total_value_cents
               FROM categories AS c LEFT JOIN products AS p ON p.category_id = c.id
               GROUP BY c.id, c.name ORDER BY c.id"""
        ).fetchall()
        return [dict(row) for row in rows]
