"""Inventory business logic and validation."""

import sqlite3
from typing import Any

from inventory.exceptions import CategoryNotFoundError, ProductNotFoundError
from inventory.models import Category, Product
from inventory.repositories.category_repository import CategoryRepository
from inventory.repositories.product_repository import ProductRepository


class InventoryService:
    def __init__(self, categories: CategoryRepository, products: ProductRepository) -> None:
        self.categories = categories
        self.products = products

    @staticmethod
    def _validate_nonnegative(name: str, value: object) -> None:
        if isinstance(value, bool) or not isinstance(value, int) or value < 0:
            raise ValueError(f"{name} must be a non-negative integer")

    def add_product(self, sku: str, name: str, category_id: int,
                    price_cents: int, stock_qty: int) -> Product:
        if self.categories.get_by_id(category_id) is None:
            raise CategoryNotFoundError(f"Category {category_id} not found")
        if self.products.find_by_sku(sku) is not None:
            raise ValueError(f"SKU {sku!r} already exists")
        self._validate_nonnegative("price_cents", price_cents)
        self._validate_nonnegative("stock_qty", stock_qty)
        if not sku.strip() or not name.strip():
            raise ValueError("SKU and name must not be empty")
        try:
            return self.products.create(Product(sku=sku, name=name, category_id=category_id,
                                                price_cents=price_cents, stock_qty=stock_qty))
        except sqlite3.IntegrityError as exc:
            raise ValueError(f"Could not add product: {exc}") from exc

    def update_product(self, product_id: int, data: dict[str, Any]) -> Product:
        if self.products.get_by_id(product_id) is None:
            raise ProductNotFoundError(f"Product {product_id} not found")
        updates = dict(data)
        if "category_id" in updates:
            if self.categories.get_by_id(updates["category_id"]) is None:
                raise CategoryNotFoundError(f"Category {updates['category_id']} not found")
        for field in ("price_cents", "stock_qty"):
            if field in updates:
                self._validate_nonnegative(field, updates[field])
        if "sku" in updates and (not isinstance(updates["sku"], str) or not updates["sku"].strip()):
            raise ValueError("SKU must not be empty")
        if "name" in updates and (not isinstance(updates["name"], str) or not updates["name"].strip()):
            raise ValueError("Name must not be empty")
        try:
            product = self.products.update(product_id, updates)
        except sqlite3.IntegrityError as exc:
            raise ValueError(f"Could not update product: {exc}") from exc
        if product is None:
            raise ProductNotFoundError(f"Product {product_id} not found")
        return product

    def delete_product(self, product_id: int) -> None:
        if not self.products.delete(product_id):
            raise ProductNotFoundError(f"Product {product_id} not found")

    def get_product_by_id(self, product_id: int) -> Product:
        product = self.products.get_by_id(product_id)
        if product is None:
            raise ProductNotFoundError(f"Product {product_id} not found")
        return product

    def list_products(self, category_id: int | None = None,
                      low_only: bool | None = None) -> list[Product]:
        products = self.products.find_low_stock() if low_only else self.products.list_all()
        if category_id is not None:
            products = [product for product in products if product.category_id == category_id]
        return products

    def restock(self, product_id: int, qty: int) -> Product:
        self._validate_nonnegative("qty", qty)
        if qty == 0:
            raise ValueError("qty must be greater than zero")
        product = self.get_product_by_id(product_id)
        return self.update_product(product_id, {"stock_qty": product.stock_qty + qty})

    def low_stock_report(self) -> list[Product]:
        return self.products.find_low_stock()

    def stock_value_by_category(self) -> list[dict[str, int | str]]:
        return self.products.stock_value_by_category()

    def add_category(self, name: str, description: str = "",
                     reorder_threshold: int | None = None) -> Category:
        if not name.strip():
            raise ValueError("Category name must not be empty")
        if reorder_threshold is not None:
            self._validate_nonnegative("reorder_threshold", reorder_threshold)
        try:
            return self.categories.create(Category(name=name, description=description,
                                                   reorder_threshold=reorder_threshold))
        except sqlite3.IntegrityError as exc:
            raise ValueError(f"Could not add category: {exc}") from exc

    def update_category(self, category_id: int, data: dict[str, Any]) -> Category:
        if self.categories.get_by_id(category_id) is None:
            raise CategoryNotFoundError(f"Category {category_id} not found")
        updates = dict(data)
        if "name" in updates and (not isinstance(updates["name"], str) or not updates["name"].strip()):
            raise ValueError("Category name must not be empty")
        if "reorder_threshold" in updates and updates["reorder_threshold"] is not None:
            self._validate_nonnegative("reorder_threshold", updates["reorder_threshold"])
        try:
            category = self.categories.update(category_id, updates)
        except sqlite3.IntegrityError as exc:
            raise ValueError(f"Could not update category: {exc}") from exc
        if category is None:
            raise CategoryNotFoundError(f"Category {category_id} not found")
        return category

    def list_categories(self) -> list[Category]:
        return self.categories.list_all()

    def delete_category(self, category_id: int) -> None:
        if self.categories.get_by_id(category_id) is None:
            raise CategoryNotFoundError(f"Category {category_id} not found")
        try:
            if not self.categories.delete(category_id):
                raise CategoryNotFoundError(f"Category {category_id} not found")
        except sqlite3.IntegrityError as exc:
            raise ValueError("Cannot delete a category that still contains products") from exc
