"""Expense application services, validation, reporting, and CSV export."""

import csv
from datetime import date
from pathlib import Path
from typing import Any

from .database import Database
from .exceptions import BudgetExceededException, CategoryNotFoundError, ExpenseNotFoundError
from .models import Budget, Category, Expense
from .repositories import BudgetRepository, CategoryRepository, ExpenseRepository


class ExpenseService:
    def __init__(
        self, database: Database | None = None, *,
        expenses: ExpenseRepository | None = None,
        categories: CategoryRepository | None = None,
        budgets: BudgetRepository | None = None,
    ) -> None:
        self.database = database or Database()
        self.expenses = expenses or ExpenseRepository(self.database)
        self.categories = categories or CategoryRepository(self.database, self.expenses)
        self.budgets = budgets or BudgetRepository(self.database)

    def add_category(self, name: str, description: str = "", monthly_budget: int | None = None, icon: str | None = None) -> Category:
        if not name.strip():
            raise ValueError("Category name must not be empty")
        if monthly_budget is not None and monthly_budget < 0:
            raise ValueError("Monthly budget cannot be negative")
        return self.categories.create(Category(name=name.strip(), description=description, monthly_budget=monthly_budget, icon=icon))

    def list_categories(self) -> list[Category]:
        return self.categories.list()

    def update_category(self, category_id: int, data: dict[str, Any]) -> Category:
        return self.categories.update(category_id, data)

    def delete_category(self, category_id: int) -> None:
        self.categories.delete(category_id)

    def list_expenses(
        self, category_id: int | None = None, start_date: date | None = None,
        end_date: date | None = None, payment_method: str | None = None,
    ) -> list[Expense]:
        if start_date and end_date and start_date > end_date:
            raise ValueError("Start date must not be after end date")
        return self.expenses.list(category_id, start_date, end_date, payment_method)

    def get_expense_by_id(self, expense_id: int) -> Expense:
        result = self.expenses.get(expense_id)
        if result is None:
            raise ExpenseNotFoundError(f"Expense {expense_id} was not found")
        return result

    def add_expense(
        self, amount_cents: int, description: str, category_id: int,
        expense_date: date | None = None, payment_method: str = "cash", is_recurring: bool = False,
    ) -> Expense:
        if amount_cents < 0:
            raise ValueError("Amount cannot be negative")
        if payment_method not in {"cash", "card", "transfer"}:
            raise ValueError("Payment method must be cash, card, or transfer")
        if self.categories.get(category_id) is None:
            raise CategoryNotFoundError(f"Category {category_id} was not found")
        item = self.expenses.create(Expense(
            amount_cents=amount_cents, description=description,
            expense_date=expense_date or date.today(), category_id=category_id,
            payment_method=payment_method, is_recurring=is_recurring,
        ))
        month = str(item.expense_date)[:7]
        if self.budgets.has_exceeded(category_id, month):
            spent = self.expenses.category_total(category_id, date.fromisoformat(f"{month}-01"), _month_end(month))
            raise BudgetExceededException(
                f"Expense saved, but category {category_id} exceeded its {month} budget ({spent} cents spent)",
                expense_id=item.id,
            )
        return item

    def update_expense(self, expense_id: int, data: dict[str, Any]) -> Expense:
        values = dict(data)
        if "category_id" in values and self.categories.get(values["category_id"]) is None:
            raise CategoryNotFoundError(f"Category {values['category_id']} was not found")
        if "payment_method" in values and values["payment_method"] not in {"cash", "card", "transfer"}:
            raise ValueError("Payment method must be cash, card, or transfer")
        if "amount_cents" in values and values["amount_cents"] < 0:
            raise ValueError("Amount cannot be negative")
        return self.expenses.update(expense_id, values)

    def delete_expense(self, expense_id: int) -> None:
        self.expenses.delete(expense_id)

    def add_budget(self, category_id: int, month: str, amount_limit_cents: int) -> Budget:
        if self.categories.get(category_id) is None:
            raise CategoryNotFoundError(f"Category {category_id} was not found")
        _validate_month(month)
        if amount_limit_cents < 0:
            raise ValueError("Budget cannot be negative")
        return self.budgets.create(Budget(category_id=category_id, month=month, amount_limit_cents=amount_limit_cents))

    def get_monthly_report(self, month: str) -> dict[str, Any]:
        _validate_month(month)
        year, month_number = map(int, month.split("-"))
        start = date(year, month_number, 1)
        end = _month_end(month)
        all_items = self.expenses.list(start_date=start, end_date=end)
        by_category: dict[int, dict[str, Any]] = {}
        for category in self.categories.list():
            budget = self.budgets.get_for_category_month(category.id or 0, month)
            limit = budget.amount_limit_cents if budget else category.monthly_budget
            by_category[category.id or 0] = {
                "category_id": category.id, "category": category.name, "total_cents": 0,
                "budget_cents": limit, "budget_status": "on_track",
            }
        for item in all_items:
            entry = by_category.setdefault(item.category_id, {
                "category_id": item.category_id, "category": str(item.category_id),
                "total_cents": 0, "budget_cents": None, "budget_status": "on_track",
            })
            entry["total_cents"] += item.amount_cents
        for entry in by_category.values():
            limit = entry["budget_cents"]
            spent = entry["total_cents"]
            if limit is not None:
                entry["budget_status"] = "exceeded" if spent > limit else "warning" if limit and spent >= limit * 0.8 else "on_track"
        return {
            "month": month, "total_spent_cents": sum(item.amount_cents for item in all_items),
            "categories": sorted(by_category.values(), key=lambda item: str(item["category"]).lower()),
        }

    def get_yearly_summary(self, year: int) -> dict[str, Any]:
        monthly = self.expenses.monthly_totals(year)
        categories = self.expenses.yearly_category_totals(year)
        total = sum(int(item["total_cents"]) for item in monthly)
        return {
            "year": year, "monthly_totals": monthly,
            "top_categories": categories[:5],
            "average_monthly_spend_cents": round(total / 12),
            "total_spent_cents": total,
        }

    def get_category_spending(self, category_id: int, start_date: date, end_date: date) -> int:
        if self.categories.get(category_id) is None:
            raise CategoryNotFoundError(f"Category {category_id} was not found")
        if start_date > end_date:
            raise ValueError("Start date must not be after end date")
        return self.expenses.category_total(category_id, start_date, end_date)

    def export_to_csv(self, file_path: str | Path, start_date: date, end_date: date) -> int:
        if start_date > end_date:
            raise ValueError("Start date must not be after end date")
        items = self.expenses.list(start_date=start_date, end_date=end_date)
        category_names = {category.id: category.name for category in self.categories.list()}
        path = Path(file_path)
        path.parent.mkdir(parents=True, exist_ok=True)
        with path.open("w", newline="", encoding="utf-8") as output:
            writer = csv.writer(output)
            writer.writerow(["id", "date", "amount", "description", "category", "payment_method", "is_recurring"])
            for item in items:
                writer.writerow([
                    item.id, item.expense_date, _money(item.amount_cents), item.description,
                    category_names.get(item.category_id, str(item.category_id)), item.payment_method,
                    str(item.is_recurring).lower(),
                ])
        return len(items)

    def detect_recurring(self) -> list[Expense]:
        grouped: dict[tuple[int, int], list[Expense]] = {}
        for item in self.expenses.list():
            grouped.setdefault((item.amount_cents, item.category_id), []).append(item)
        marked: list[Expense] = []
        for items in grouped.values():
            distinct_months = {str(item.expense_date)[:7] for item in items}
            if len(distinct_months) >= 2:
                for item in items:
                    if not item.is_recurring:
                        marked.append(self.expenses.update(item.id or 0, {"is_recurring": True}))
        return marked


def _validate_month(month: str) -> None:
    try:
        parsed = date.fromisoformat(f"{month}-01")
    except ValueError as exc:
        raise ValueError("Month must be in YYYY-MM format") from exc
    if parsed.strftime("%Y-%m") != month:
        raise ValueError("Month must be in YYYY-MM format")


def _month_end(month: str) -> date:
    year, month_number = map(int, month.split("-"))
    if month_number == 12:
        return date(year, 12, 31)
    return date(year, month_number + 1, 1).fromordinal(date(year, month_number + 1, 1).toordinal() - 1)


def _money(cents: int) -> str:
    return f"{cents // 100}.{cents % 100:02d}"
