"""Click command-line interface."""

from datetime import date
from decimal import Decimal, InvalidOperation
from typing import Any

import click

from .database import Database
from .exceptions import BudgetExceededException, ExpenseTrackerError
from .services import ExpenseService


def _service() -> ExpenseService:
    return ExpenseService(Database())


def _date(value: str) -> date:
    try:
        return date.fromisoformat(value)
    except ValueError as exc:
        raise click.BadParameter("must be an ISO date (YYYY-MM-DD)") from exc


def _cents(value: str) -> int:
    try:
        amount = Decimal(value)
        if not amount.is_finite() or amount < 0:
            raise InvalidOperation
        cents = amount * 100
        if cents != cents.to_integral_value():
            raise click.BadParameter("must have no more than two decimal places")
        return int(cents)
    except InvalidOperation as exc:
        raise click.BadParameter("must be a non-negative monetary amount") from exc


def _display(cents: int | None) -> str:
    return "—" if cents is None else f"${cents // 100}.{cents % 100:02d}"


def _run(action: Any) -> Any:
    try:
        return action()
    except (ExpenseTrackerError, ValueError, LookupError) as exc:
        raise click.ClickException(str(exc)) from exc


@click.group(name="expense")
def expense_cli() -> None:
    """Track expenses, categories, and reports."""


@expense_cli.group("category")
def category_group() -> None:
    """Manage expense categories."""


@category_group.command("add")
@click.option("--name", required=True)
@click.option("--description", required=True)
@click.option("--budget", help="Monthly category budget in currency units.")
@click.option("--icon")
def category_add(name: str, description: str, budget: str | None, icon: str | None) -> None:
    item = _run(lambda: _service().add_category(name, description, _cents(budget) if budget is not None else None, icon))
    click.echo(f"Created category {item.id}: {item.name}")


@category_group.command("list")
def category_list() -> None:
    for item in _service().list_categories():
        click.echo(f"{item.id}\t{item.name}\t{_display(item.monthly_budget)}\t{item.description}")


@category_group.command("update")
@click.option("--id", "category_id", required=True, type=int)
@click.option("--name")
@click.option("--description")
@click.option("--budget")
@click.option("--icon")
def category_update(category_id: int, name: str | None, description: str | None, budget: str | None, icon: str | None) -> None:
    data: dict[str, Any] = {k: v for k, v in {"name": name, "description": description, "monthly_budget": _cents(budget) if budget is not None else None, "icon": icon}.items() if v is not None}
    item = _run(lambda: _service().update_category(category_id, data))
    click.echo(f"Updated category {item.id}: {item.name}")


@category_group.command("delete")
@click.option("--id", "category_id", required=True, type=int)
def category_delete(category_id: int) -> None:
    _run(lambda: _service().delete_category(category_id))
    click.echo(f"Deleted category {category_id}")


@expense_cli.command("add")
@click.option("--amount", required=True, help="Amount in currency units (e.g. 12.50).")
@click.option("--description", required=True)
@click.option("--category", "category_value", required=True)
@click.option("--expense-date", default=None)
@click.option("--method", type=click.Choice(["cash", "card", "transfer"]), default="cash", show_default=True)
@click.option("--recurring", is_flag=True)
def expense_add(amount: str, description: str, category_value: str, expense_date: str | None, method: str, recurring: bool) -> None:
    service = _service()
    try:
        category_id = int(category_value)
    except ValueError:
        category = next((c for c in service.list_categories() if c.name == category_value), None)
        if category is None:
            raise click.ClickException(f"Category {category_value!r} was not found")
        category_id = category.id or 0
    item = _run(lambda: service.add_expense(_cents(amount), description, category_id, _date(expense_date) if expense_date else None, method, recurring))
    click.echo(f"Created expense {item.id}: {_display(item.amount_cents)}")


@expense_cli.command("list")
@click.option("--category", type=int)
@click.option("--from-date")
@click.option("--to-date")
@click.option("--method", type=click.Choice(["cash", "card", "transfer"]))
def expense_list(category: int | None, from_date: str | None, to_date: str | None, method: str | None) -> None:
    items = _run(lambda: _service().list_expenses(category, _date(from_date) if from_date else None, _date(to_date) if to_date else None, method))
    click.echo("ID\tDATE\tAMOUNT\tCATEGORY\tMETHOD\tDESCRIPTION\tRECURRING")
    for item in items:
        click.echo(f"{item.id}\t{item.expense_date}\t{_display(item.amount_cents)}\t{item.category_id}\t{item.payment_method}\t{item.description}\t{item.is_recurring}")


@expense_cli.group("report")
def report_group() -> None:
    """Expense summaries."""


@report_group.command("monthly")
@click.option("--month", required=True)
def report_monthly(month: str) -> None:
    report = _run(lambda: _service().get_monthly_report(month))
    click.echo(f"Monthly report {month}: total {_display(report['total_spent_cents'])}")
    click.echo("CATEGORY\tSPENT\tBUDGET\tSTATUS")
    for row in report["categories"]:
        click.echo(f"{row['category']}\t{_display(row['total_cents'])}\t{_display(row['budget_cents'])}\t{row['budget_status']}")


@report_group.command("yearly")
@click.option("--year", required=True, type=click.IntRange(1, 9999))
def report_yearly(year: int) -> None:
    report = _run(lambda: _service().get_yearly_summary(year))
    click.echo(f"Yearly report {year}: total {_display(report['total_spent_cents'])}; average monthly {_display(report['average_monthly_spend_cents'])}")
    click.echo("MONTH\tTOTAL")
    for row in report["monthly_totals"]:
        click.echo(f"{row['month']}\t{_display(row['total_cents'])}")
    click.echo("TOP CATEGORIES")
    for row in report["top_categories"]:
        click.echo(f"{row['category']}\t{_display(row['total_cents'])}")


@expense_cli.command("export")
@click.option("--from-date", required=True)
@click.option("--to-date", required=True)
