--- inventory CLI
"""Click command-line interface for inventory operations."""

from dataclasses import asdict, is_dataclass
from functools import wraps
import json
from typing import Any, Callable, TypeVar

import click

from inventory.database import Database
from inventory.repositories.category_repository import CategoryRepository
from inventory.repositories.product_repository import ProductRepository
from inventory.services.inventory_service import InventoryService

F = TypeVar("F", bound=Callable[..., Any])


def domain_errors(function: F) -> F:
    """Present expected domain/validation failures as concise CLI errors."""
    @wraps(function)
    def wrapped(*args: Any, **kwargs: Any) -> Any:
        try:
            return function(*args, **kwargs)
        except (LookupError, ValueError) as exc:
            raise click.ClickException(str(exc)) from exc
    return wrapped  # type: ignore[return-value]


def emit(value: Any) -> None:
    def convert(item: Any) -> Any:
        if is_dataclass(item):
            return asdict(item)
        raise TypeError(f"Cannot serialize {type(item).__name__}")
    click.echo(json.dumps(value, default=convert, indent=2))


@click.group()
@click.option("--db-path", envvar="INVENTORY_DB", default="inventory.db",
              show_default=True, type=click.Path(file_okay=True, dir_okay=False),
              help="SQLite database file.")
@click.pass_context
def cli(ctx: click.Context, db_path: str) -> None:
    """Manage product inventory and categories."""
    database = Database(db_path)
    ctx.call_on_close(database.close)
    ctx.obj = {"database": database,
               "service": InventoryService(CategoryRepository(database), ProductRepository(database))}


@cli.group()
def product() -> None:
    """Create, inspect, and update products."""


@product.command("add")
@click.option("--sku", required=True, help="Unique stock-keeping unit.")
@click.option("--name", required=True)
@click.option("--category", "category_id", required=True, type=int, help="Category ID.")
@click.option("--price", "price_cents", required=True, type=click.IntRange(min=0),
              help="Unit price in integer cents.")
@click.option("--stock", "stock_qty", required=True, type=click.IntRange(min=0))
@click.pass_context
@domain_errors
def product_add(ctx: click.Context, sku: str, name: str, category_id: int,
                price_cents: int, stock_qty: int) -> None:
    """Add a product; monetary price is supplied in cents."""
    emit(ctx.obj["service"].add_product(sku, name, category_id, price_cents, stock_qty))


@product.command("list")
@click.option("--category", "category_id", type=int, help="Filter by category ID.")
@click.option("--low-only", is_flag=True, help="Show products below their category threshold.")
@click.pass_context
def product_list(ctx: click.Context, category_id: int | None, low_only: bool) -> None:
    """List products, optionally filtered by category and low stock."""
    emit(ctx.obj["service"].list_products(category_id, low_only))


@product.command("update")
@click.option("--id", "product_id", required=True, type=int)
@click.option("--name")
@click.option("--price", "price_cents", type=click.IntRange(min=0), help="Unit price in cents.")
@click.option("--category", "category_id", type=int, help="New category ID.")
@click.pass_context
@domain_errors
def product_update(ctx: click.Context, product_id: int, name: str | None,
                   price_cents: int | None, category_id: int | None) -> None:
    """Update the supplied product fields."""
    data = {key: value for key, value in {"name": name, "price_cents": price_cents,
                                          "category_id": category_id}.items() if value is not None}
    emit(ctx.obj["service"].update_product(product_id, data))


@product.command("delete")
@click.option("--id", "product_id", required=True, type=int)
@click.pass_context
@domain_errors
def product_delete(ctx: click.Context, product_id: int) -> None:
    """Delete a product by ID."""
    ctx.obj["service"].delete_product(product_id)
    click.echo(f"Deleted product {product_id}")


@product.command("restock")
@click.option("--id", "product_id", required=True, type=int)
@click.option("--qty", required=True, type=click.IntRange(min=1))
@click.pass_context
@domain_errors
def product_restock(ctx: click.Context, product_id: int, qty: int) -> None:
    """Increase a product's stock quantity."""
    emit(ctx.obj["service"].restock(product_id, qty))


@product.group("report")
def product_report() -> None:
    """Inventory reports."""


@product_report.command("low-stock")
@click.pass_context
def product_report_low_stock(ctx: click.Context) -> None:
    """Show products below their category's reorder threshold."""
    emit(ctx.obj["service"].low_stock_report())


@product_report.command("value")
@click.pass_context
def product_report_value(ctx: click.Context) -> None:
    """Show stock value totals by category, in cents."""
    emit(ctx.obj["service"].stock_value_by_category())


@cli.group()
def category() -> None:
    """Create, inspect, and update product categories."""


@category.command("add")
@click.option("--name", required=True)
@click.option("--description", default="", show_default=True)
@click.option("--threshold", "reorder_threshold", type=click.IntRange(min=0))
@click.pass_context
@domain_errors
