"""Domain constants and validation, independent of SQLite and the CLI."""

from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
import re

from .errors import ValidationError

ORDER_STATUSES = ("pending", "confirmed", "shipped", "cancelled")
_EMAIL = re.compile(r"^[^\s@]+@[^\s@]+\.[^\s@]+$")


def required_text(value: str, label: str, *, max_length: int = 200) -> str:
    value = value.strip()
    if not value:
        raise ValidationError(f"{label} is required")
    if len(value) > max_length:
        raise ValidationError(f"{label} must be at most {max_length} characters")
    return value


def validate_email(value: str) -> str:
    value = required_text(value, "Email", max_length=254)
    if not _EMAIL.fullmatch(value):
        raise ValidationError("Email address is not valid")
    return value


def positive_int(value: int, label: str) -> int:
    if isinstance(value, bool) or not isinstance(value, int) or value <= 0:
        raise ValidationError(f"{label} must be a positive integer")
    return value


def nonnegative_int(value: int, label: str) -> int:
    if isinstance(value, bool) or not isinstance(value, int) or value < 0:
        raise ValidationError(f"{label} must be a non-negative integer")
    return value


def money_to_cents(value: str | Decimal | int) -> int:
    try:
        amount = Decimal(str(value)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
    except (InvalidOperation, ValueError):
        raise ValidationError("Price must be a valid amount, such as 12.50") from None
    if not amount.is_finite() or amount <= 0:
        raise ValidationError("Price must be greater than zero")
    if amount > Decimal("999999999.99"):
        raise ValidationError("Price is too large")
    return int(amount * 100)


def format_money(cents: int) -> str:
    return f"{cents // 100}.{cents % 100:02d}"
