"""Business operations and lifecycle rules."""

from datetime import datetime, timezone
import sqlite3

from .database import Database
from .domain import (
    format_money, money_to_cents, nonnegative_int, positive_int,
    required_text, validate_email,
)
from .errors import (
    InsufficientStockError, NotFoundError, StateError, ValidationError,
)
from .repository import Repository


def _now() -> str:
    return datetime.now(timezone.utc).isoformat(timespec="seconds")


def _required(repo: Repository, table: str, record_id: int, label: str):
    row = repo.one(f"SELECT * FROM {table} WHERE id = ?", (record_id,))
    if row is None:
        raise NotFoundError(f"{label} {record_id} was not found")
    return row


class ShopService:
    def __init__(self, database: Database):
        self.database = database
        database.initialize()

    def add_customer(self, name: str, email: str) -> int:
        name, email, now = required_text(name, "Customer name"), validate_email(email), _now()
        try:
            with self.database.transaction() as conn:
                return Repository(conn).insert(
                    "INSERT INTO customers(name,email,created_at) VALUES(?,?,?)", (name, email, now)
                )
        except sqlite3.IntegrityError as error:
            if "customers.email" in str(error):
                raise ValidationError("A customer with that email already exists") from None
            raise

    def list_customers(self):
        with self.database.connect() as conn:
            return Repository(conn).all("SELECT * FROM customers ORDER BY name COLLATE NOCASE")

    def add_category(self, name: str) -> int:
        name, now = required_text(name, "Category name"), _now()
        try:
            with self.database.transaction() as conn:
                return Repository(conn).insert("INSERT INTO categories(name,created_at) VALUES(?,?)", (name, now))
        except sqlite3.IntegrityError:
            raise ValidationError("A category with that name already exists") from None

    def rename_category(self, category_id: int, name: str) -> None:
        name = required_text(name, "Category name")
        try:
            with self.database.transaction() as conn:
                repo = Repository(conn)
                _required(repo, "categories", category_id, "Category")
                repo.run("UPDATE categories SET name=? WHERE id=?", (name, category_id))
        except sqlite3.IntegrityError:
            raise ValidationError("A category with that name already exists") from None

    def list_categories(self):
        with self.database.connect() as conn:
            return Repository(conn).all("SELECT * FROM categories ORDER BY name COLLATE NOCASE")

    def add_product(self, category_id: int, name: str, price: str, stock: int, description: str = "") -> int:
        name = required_text(name, "Product name")
        description = description.strip()
        if len(description) > 2000:
            raise ValidationError("Description must be at most 2000 characters")
        cents, stock, now = money_to_cents(price), nonnegative_int(stock, "Stock quantity"), _now()
        with self.database.transaction() as conn:
            repo = Repository(conn)
            _required(repo, "categories", category_id, "Category")
            return repo.insert(
                "INSERT INTO products(category_id,name,description,price_cents,stock_on_hand,created_at) VALUES(?,?,?,?,?,?)",
                (category_id, name, description, cents, stock, now),
            )

    def update_product(self, product_id: int, *, name: str | None = None, category_id: int | None = None,
                       price: str | None = None, stock: int | None = None,
                       description: str | None = None, active: bool | None = None) -> None:
        with self.database.transaction() as conn:
            repo = Repository(conn)
            product = _required(repo, "products", product_id, "Product")
            fields, values = [], []
            if name is not None:
                fields.append("name=?"); values.append(required_text(name, "Product name"))
            if category_id is not None:
                _required(repo, "categories", category_id, "Category")
                fields.append("category_id=?"); values.append(category_id)
            if price is not None:
                fields.append("price_cents=?"); values.append(money_to_cents(price))
            if stock is not None:
                stock = nonnegative_int(stock, "Stock quantity")
                if stock < product["reserved_quantity"]:
                    raise ValidationError("Stock cannot be lower than the quantity reserved by confirmed orders")
                fields.append("stock_on_hand=?"); values.append(stock)
            if description is not None:
                description = description.strip()
                if len(description) > 2000:
                    raise ValidationError("Description must be at most 2000 characters")
                fields.append("description=?"); values.append(description)
            if active is not None:
                fields.append("active=?"); values.append(int(active))
            if fields:
                values.append(product_id)
                repo.run(f"UPDATE products SET {','.join(fields)} WHERE id=?", tuple(values))

    def list_products(self, include_inactive: bool = False):
        sql = "SELECT p.*, c.name AS category_name, p.stock_on_hand-p.reserved_quantity AS available FROM products p JOIN categories c ON c.id=p.category_id"
        if not include_inactive:
            sql += " WHERE p.active=1"
        sql += " ORDER BY p.name COLLATE NOCASE"
        with self.database.connect() as conn:
            return Repository(conn).all(sql)

    def create_order(self, customer_id: int, items: list[tuple[int, int]]) -> int:
        if not items:
            raise ValidationError("An order must contain at least one product")
        quantities: dict[int, int] = {}
        for product_id, quantity in items:
            positive_int(product_id, "Product ID")
            positive_int(quantity, "Item quantity")
            quantities[product_id] = quantities.get(product_id, 0) + quantity
        with self.database.transaction() as conn:
            repo = Repository(conn)
            _required(repo, "customers", customer_id, "Customer")
            products = []
            for product_id, quantity in quantities.items():
                product = _required(repo, "products", product_id, "Product")
                if not product["active"]:
                    raise ValidationError(f"Product {product_id} is inactive")
                if product["stock_on_hand"] - product["reserved_quantity"] < quantity:
                    raise InsufficientStockError(f"Not enough available stock for {product['name']}")
                products.append((product, quantity))
            now = _now()
            order_id = repo.insert(
                "INSERT INTO orders(customer_id,status,created_at,updated_at) VALUES(?,?,?,?)",
                (customer_id, "pending", now, now),
            )
            for product, quantity in products:
                repo.run(
                    "INSERT INTO order_items(order_id,product_id,product_name,quantity,unit_price_cents) VALUES(?,?,?,?,?)",
                    (order_id, product["id"], product["name"], quantity, product["price_cents"]),
                )
            return order_id

    def confirm_order(self, order_id: int) -> int:
        with self.database.transaction() as conn:
            repo = Repository(conn)
            order = _required(repo, "orders", order_id, "Order")
            if order["status"] != "pending":
                raise StateError("Only pending orders can be confirmed")
            items = repo.all("SELECT * FROM order_items WHERE order_id=?", (order_id,))
            if not items:
                raise StateError("An empty order cannot be confirmed")
            for item in items:
                product = _required(repo, "products", item["product_id"], "Product")
                available = product["stock_on_hand"] - product["reserved_quantity"]
                if available < item["quantity"]:
                    raise InsufficientStockError(f"Not enough available stock for {product['name']}")
            for item in items:
                repo.run("UPDATE products SET reserved_quantity=reserved_quantity+? WHERE id=?",
                         (item["quantity"], item["product_id"]))
            now = _now()
            repo.run("UPDATE orders SET status='confirmed',updated_at=? WHERE id=?", (now, order_id))
            total = sum(item["quantity"] * item["unit_price_cents"] for item in items)
            return repo.insert(
                "INSERT INTO invoices(order_id,customer_id,total_cents,created_at) VALUES(?,?,?,?)",
                (order_id, order["customer_id"], total, now),
            )

    def cancel_order(self, order_id: int) -> None:
        with self.database.transaction() as conn:
            repo = Repository(conn)
            order = _required(repo, "orders", order_id, "Order")
            if order["status"] not in ("pending", "confirmed"):
                raise StateError("Only pending or confirmed orders can be cancelled")
            if order["status"] == "confirmed":
                for item in repo.all("SELECT product_id,quantity FROM order_items WHERE order_id=?", (order_id,)):
                    repo.run("UPDATE products SET reserved_quantity=reserved_quantity-? WHERE id=?",
                             (item["quantity"], item["product_id"]))
            repo.run("UPDATE orders SET status='cancelled',updated_at=? WHERE id=?", (_now(), order_id))

    def ship_order(self, order_id: int) -> None:
        with self.database.transaction() as conn:
            repo = Repository(conn)
            order = _required(repo, "orders", order_id, "Order")
            if order["status"] != "confirmed":
                raise StateError("Only confirmed orders can be shipped")
            for item in repo.all("SELECT product_id,quantity FROM order_items WHERE order_id=?", (order_id,)):
                repo.run("UPDATE products SET stock_on_hand=stock_on_hand-?, reserved_quantity=reserved_quantity-? WHERE id=?",
                         (item["quantity"], item["quantity"], item["product_id"]))
            repo.run("UPDATE orders SET status='shipped',updated_at=? WHERE id=?", (_now(), order_id))

    def order_details(self, order_id: int):
        with self.database.connect() as conn:
            repo = Repository(conn)
            order = repo.one("SELECT o.*,c.name AS customer_name,c.email FROM orders o JOIN customers c ON c.id=o.customer_id WHERE o.id=?", (order_id,))
            if order is None:
                raise NotFoundError(f"Order {order_id} was not found")
            items = repo.all("SELECT * FROM order_items WHERE order_id=? ORDER BY id", (order_id,))
            total = sum(i["quantity"] * i["unit_price_cents"] for i in items)
            return {"order": order, "items": items, "total_cents": total}

    def search_orders(self, customer_id: int, *, status: str | None = None, query: str | None = None):
        if status is not None and status not in ("pending", "confirmed", "shipped", "cancelled"):
            raise ValidationError("Unknown order status")
        with self.database.connect() as conn:
            repo = Repository(conn)
            _required(repo, "customers", customer_id, "Customer")
            sql = "SELECT o.*, COALESCE(SUM(oi.quantity*oi.unit_price_cents),0) AS total_cents FROM orders o LEFT JOIN order_items oi ON oi.order_id=o.id WHERE o.customer_id=?"
            params: list = [customer_id]
            if status:
                sql += " AND o.status=?"; params.append(status)
            if query:
                if query.isdigit():
                    sql += " AND o.id=?"; params.append(int(query))
                else:
                    sql += " AND CAST(o.id AS TEXT) LIKE ?"; params.append(f"%{query}%")
            sql += " GROUP BY o.id ORDER BY o.created_at DESC"
            return repo.all(sql, tuple(params))

    def search_invoices(self, customer_id: int, *, query: str | None = None):
        with self.database.connect() as conn:
            repo = Repository(conn)
            _required(repo, "customers", customer_id, "Customer")
            sql = "SELECT i.*,o.status AS order_status FROM invoices i JOIN orders o ON o.id=i.order_id WHERE i.customer_id=?"
            params: list = [customer_id]
            if query:
                if query.isdigit():
                    sql += " AND (i.id=? OR i.order_id=?)"; params.extend([int(query), int(query)])
                else:
                    sql += " AND (CAST(i.id AS TEXT) LIKE ? OR CAST(i.order_id AS TEXT) LIKE ?)"
                    params.extend([f"%{query}%", f"%{query}%"])
            sql += " ORDER BY i.created_at DESC"
            return repo.all(sql, tuple(params))

    def invoice_details(self, invoice_id: int):
        with self.database.connect() as conn:
            repo = Repository(conn)
            invoice = repo.one("SELECT i.*,c.name AS customer_name,c.email,o.status AS order_status FROM invoices i JOIN customers c ON c.id=i.customer_id JOIN orders o ON o.id=i.order_id WHERE i.id=?", (invoice_id,))
            if invoice is None:
                raise NotFoundError(f"Invoice {invoice_id} was not found")
            items = repo.all("SELECT * FROM order_items WHERE order_id=? ORDER BY id", (invoice["order_id"],))
            return {"invoice": invoice, "items": items}


