import sqlite3
from datetime import date
from typing import Any

from .database import Database
from .exceptions import CategoryNotFoundError, ExpenseNotFoundError
from .models import Budget, Category, Expense


def _expense(row: sqlite3.Row | None) -> Expense | None:
    if row is None:
        return None
    return Expense(
        id=row["id"], amount_cents=row["amount_cents"], description=row["description"],
        expense_date=date.fromisoformat(row["expense_date"]), category_id=row["category_id"],
        payment_method=row["payment_method"], is_recurring=bool(row["is_recurring"]),
    )


def _category(row: sqlite3.Row | None) -> Category | None:
    return None if row is None else Category(**dict(row))


def _budget(row: sqlite3.Row | None) -> Budget | None:
    return None if row is None else Budget(**dict(row))


class ExpenseRepository:
    def __init__(self, database: Database) -> None:
        self.db = database

    def create(self, item: Expense) -> Expense:
        with self.db.transaction() as conn:
            cur = conn.execute(
                "INSERT INTO expenses(amount_cents, description, expense_date, category_id, payment_method, is_recurring) VALUES (?, ?, ?, ?, ?, ?)",
                (item.amount_cents, item.description, str(item.expense_date), item.category_id,
                 item.payment_method, int(item.is_recurring)),
            )
            item.id = cur.lastrowid
        return item

    def get(self, expense_id: int) -> Expense | None:
        return _expense(self.db.connection.execute("SELECT * FROM expenses WHERE id = ?", (expense_id,)).fetchone())

    def list(
        self, category_id: int | None = None, start_date: date | None = None,
        end_date: date | None = None, payment_method: str | None = None,
    ) -> list[Expense]:
        clauses: list[str] = []
        values: list[Any] = []
        if category_id is not None:
            clauses.append("category_id = ?")
            values.append(category_id)
        if start_date is not None:
            clauses.append("expense_date >= ?")
            values.append(start_date.isoformat())
        if end_date is not None:
            clauses.append("expense_date <= ?")
            values.append(end_date.isoformat())
        if payment_method is not None:
            clauses.append("payment_method = ?")
            values.append(payment_method)
        where = f" WHERE {' AND '.join(clauses)}" if clauses else ""
        rows = self.db.connection.execute(f"SELECT * FROM expenses{where} ORDER BY expense_date, id", values)
        return [item for row in rows if (item := _expense(row)) is not None]

    def update(self, expense_id: int, fields: dict[str, Any]) -> Expense:
        allowed = {"amount_cents", "description", "expense_date", "category_id", "payment_method", "is_recurring"}
        updates = {key: value for key, value in fields.items() if key in allowed}
        if updates:
            if "expense_date" in updates:
                updates["expense_date"] = str(updates["expense_date"])
            if "is_recurring" in updates:
                updates["is_recurring"] = int(updates["is_recurring"])
            assignments = ", ".join(f"{key} = ?" for key in updates)
            with self.db.transaction() as conn:
                cur = conn.execute(f"UPDATE expenses SET {assignments} WHERE id = ?", (*updates.values(), expense_id))
                if not cur.rowcount:
                    raise ExpenseNotFoundError(f"Expense {expense_id} was not found")
        result = self.get(expense_id)
        if result is None:
            raise ExpenseNotFoundError(f"Expense {expense_id} was not found")
        return result

    def delete(self, expense_id: int) -> None:
        with self.db.transaction() as conn:
            cur = conn.execute("DELETE FROM expenses WHERE id = ?", (expense_id,))
            if not cur.rowcount:
                raise ExpenseNotFoundError(f"Expense {expense_id} was not found")

    def monthly_totals(self, year: int) -> list[dict[str, int | str]]:
        rows = self.db.connection.execute(
            "SELECT substr(expense_date, 1, 7) AS month, SUM(amount_cents) AS total_cents FROM expenses WHERE expense_date >= ? AND expense_date < ? GROUP BY month ORDER BY month",
            (f"{year:04d}-01-01", f"{year + 1:04d}-01-01"),
        )
        return [{"month": row["month"], "total_cents": row["total_cents"]} for row in rows]

    def yearly_category_totals(self, year: int) -> list[dict[str, int | str]]:
        rows = self.db.connection.execute(
            "SELECT c.id AS category_id, c.name AS category, SUM(e.amount_cents) AS total_cents FROM expenses e JOIN categories c ON c.id=e.category_id WHERE e.expense_date >= ? AND e.expense_date < ? GROUP BY c.id, c.name ORDER BY total_cents DESC, c.name",
            (f"{year:04d}-01-01", f"{year + 1:04d}-01-01"),
        )
        return [dict(row) for row in rows]

    def category_total(self, category_id: int, start_date: date, end_date: date) -> int:
        row = self.db.connection.execute(
            "SELECT COALESCE(SUM(amount_cents), 0) AS total FROM expenses WHERE category_id=? AND expense_date>=? AND expense_date<=?",
            (category_id, start_date.isoformat(), end_date.isoformat()),
        ).fetchone()
        return int(row["total"])


