    def get_for_category_month(self, category_id: int, month: str) -> Budget | None:
        return _budget(self.db.connection.execute("SELECT * FROM budgets WHERE category_id=? AND month=?", (category_id, month)).fetchone())

    def list(self, category_id: int | None = None, month: str | None = None) -> list[Budget]:
        clauses: list[str] = []
        params: list[Any] = []
        if category_id is not None:
            clauses.append("category_id=?")
            params.append(category_id)
        if month is not None:
            clauses.append("month=?")
            params.append(month)
        where = f" WHERE {' AND '.join(clauses)}" if clauses else ""
        return [_budget(row) for row in self.db.connection.execute(f"SELECT * FROM budgets{where} ORDER BY month, category_id", params)]  # type: ignore[misc]

    def update(self, category_id: int, month: str, amount_limit_cents: int) -> Budget:
        with self.db.transaction() as conn:
            cur = conn.execute("UPDATE budgets SET amount_limit_cents=? WHERE category_id=? AND month=?", (amount_limit_cents, category_id, month))
            if not cur.rowcount:
                raise LookupError(f"Budget for category {category_id} in {month} was not found")
        result = self.get_for_category_month(category_id, month)
        assert result is not None
        return result

    def delete(self, category_id: int, month: str) -> None:
        with self.db.transaction() as conn:
            cur = conn.execute("DELETE FROM budgets WHERE category_id=? AND month=?", (category_id, month))
            if not cur.rowcount:
                raise LookupError(f"Budget for category {category_id} in {month} was not found")

    def find_by_month(self, month: str) -> list[Budget]:
        return self.list(month=month)

    def has_exceeded(self, category_id: int, month: str, spent_cents: int | None = None) -> bool:
        budget = self.get_for_category_month(category_id, month)
        if budget is None:
            row = self.db.connection.execute("SELECT monthly_budget FROM categories WHERE id=?", (category_id,)).fetchone()
            limit = None if row is None else row["monthly_budget"]
        else:
            limit = budget.amount_limit_cents
        if limit is None:
            return False
        if spent_cents is None:
            row = self.db.connection.execute(
                "SELECT COALESCE(SUM(amount_cents), 0) AS total FROM expenses WHERE category_id=? AND substr(expense_date,1,7)=?",
                (category_id, month),
            ).fetchone()
            spent_cents = int(row["total"])
        return spent_cents > limit

"""SQLite repositories; repositories persist data but do not own business rules."""

import sqlite3
from datetime import date
from typing import Any

from library_system.errors import DuplicateValueError, InvalidCopyCountError, NotFoundError
from library_system.models import Author, Book, Loan, Member


def _date(value: str | None) -> date | None:
    return date.fromisoformat(value) if value is not None else None


def _book(row: sqlite3.Row) -> Book:
    return Book(
        id=row["id"], title=row["title"], isbn=row["isbn"], author_id=row["author_id"],
        published_year=row["published_year"], available_copies=row["available_copies"],
    )


def _author(row: sqlite3.Row) -> Author:
    return Author(id=row["id"], name=row["name"], birth_year=row["birth_year"], biography=row["biography"])


def _member(row: sqlite3.Row) -> Member:
    return Member(
        id=row["id"], name=row["name"], email=row["email"],
        membership_date=date.fromisoformat(row["membership_date"]), is_active=bool(row["is_active"]),
    )


def _loan(row: sqlite3.Row, *, status: str | None = None) -> Loan:
    return Loan(
        id=row["id"], book_id=row["book_id"], member_id=row["member_id"],
        loan_date=date.fromisoformat(row["loan_date"]), due_date=date.fromisoformat(row["due_date"]),
        return_date=_date(row["return_date"]), status=status or row["status"],
    )


def _translate_integrity(error: sqlite3.IntegrityError, field: str) -> Exception:
    if "UNIQUE constraint failed" in str(error):
        return DuplicateValueError(f"{field} must be unique")
    return error


def _like(query: str) -> str:
    """Build a literal substring pattern for SQL LIKE."""
    return "%" + query.replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_") + "%"


class BookRepository:
    def __init__(self, connection: sqlite3.Connection) -> None:
        self.connection = connection

    def create(self, book: Book) -> Book:
        if book.available_copies < 0:
            raise InvalidCopyCountError("available_copies cannot be negative")
        try:
            cursor = self.connection.execute(
                "INSERT INTO books(title,isbn,author_id,published_year,available_copies) VALUES(?,?,?,?,?)",
                (book.title, book.isbn, book.author_id, book.published_year, book.available_copies),
            )
        except sqlite3.IntegrityError as error:
            raise _translate_integrity(error, "ISBN") from error
        return self.get(cursor.lastrowid)

    def get(self, book_id: int) -> Book:
        row = self.connection.execute("SELECT * FROM books WHERE id=?", (book_id,)).fetchone()
        if row is None:
            raise NotFoundError(f"Book {book_id} was not found")
        return _book(row)

    def list(self, *, author_id: int | None = None, available_only: bool = False) -> list[Book]:
        sql = "SELECT * FROM books WHERE 1=1"
        params: list[Any] = []
        if author_id is not None:
            sql += " AND author_id=?"
            params.append(author_id)
        if available_only:
            sql += " AND available_copies > 0"
        sql += " ORDER BY id"
        return [_book(row) for row in self.connection.execute(sql, params).fetchall()]

    def update(self, book: Book) -> Book:
        if book.id is None:
            raise ValueError("book.id is required for update")
        if book.available_copies < 0:
            raise InvalidCopyCountError("available_copies cannot be negative")
        try:
            cursor = self.connection.execute(
                "UPDATE books SET title=?,isbn=?,author_id=?,published_year=?,available_copies=? WHERE id=?",
                (book.title, book.isbn, book.author_id, book.published_year, book.available_copies, book.id),
            )
        except sqlite3.IntegrityError as error:
            raise _translate_integrity(error, "ISBN") from error
        if cursor.rowcount == 0:
            raise NotFoundError(f"Book {book.id} was not found")
        return self.get(book.id)

    def delete(self, book_id: int) -> None:
        cursor = self.connection.execute("DELETE FROM books WHERE id=?", (book_id,))
        if cursor.rowcount == 0:
            raise NotFoundError(f"Book {book_id} was not found")

    def search(self, query: str) -> list[Book]:
        needle = _like(query)
        rows = self.connection.execute(
            """SELECT DISTINCT b.* FROM books b JOIN authors a ON a.id=b.author_id
               WHERE lower(b.title) LIKE lower(?) ESCAPE '\\'
                  OR lower(a.name) LIKE lower(?) ESCAPE '\\'
                  OR lower(b.isbn) LIKE lower(?) ESCAPE '\\'
               ORDER BY b.id""",
            (needle, needle, needle),
        ).fetchall()
        return [_book(row) for row in rows]

    def search_by_title(self, query: str) -> list[Book]:
        rows = self.connection.execute(
            "SELECT * FROM books WHERE lower(title) LIKE lower(?) ESCAPE '\\' ORDER BY id", (_like(query),)
        ).fetchall()
        return [_book(row) for row in rows]

    def search_by_isbn(self, query: str) -> list[Book]:
        rows = self.connection.execute(
            "SELECT * FROM books WHERE lower(isbn) LIKE lower(?) ESCAPE '\\' ORDER BY id", (_like(query),)
        ).fetchall()
        return [_book(row) for row in rows]

    def search_by_author(self, query: str) -> list[Book]:
        rows = self.connection.execute(
            """SELECT b.* FROM books b JOIN authors a ON a.id=b.author_id
               WHERE lower(a.name) LIKE lower(?) ESCAPE '\\' ORDER BY b.id""",
            (_like(query),),
        ).fetchall()
        return [_book(row) for row in rows]

    def set_available_copies(self, book_id: int, copies: int) -> Book:
        if copies < 0:
            raise InvalidCopyCountError("available_copies cannot be negative")
        cursor = self.connection.execute("UPDATE books SET available_copies=? WHERE id=?", (copies, book_id))
        if cursor.rowcount == 0:
            raise NotFoundError(f"Book {book_id} was not found")
        return self.get(book_id)

    def adjust_available_copies(self, book_id: int, amount: int) -> Book:
        cursor = self.connection.execute(
            "UPDATE books SET available_copies=available_copies+? WHERE id=? AND available_copies+? >= 0",
            (amount, book_id, amount),
        )
        if cursor.rowcount == 0:
            if self.connection.execute("SELECT 1 FROM books WHERE id=?", (book_id,)).fetchone() is None:
                raise NotFoundError(f"Book {book_id} was not found")
            raise InvalidCopyCountError("available_copies cannot be negative")
        return self.get(book_id)


