"""Application services and transactional library use cases."""

from datetime import date, timedelta

from library_system.database import Database
from library_system.errors import AlreadyReturnedLoanError, BookNotAvailableError, InactiveMemberError
from library_system.models import Author, Book, Loan, Member
from library_system.repositories import AuthorRepository, BookRepository, LoanRepository, MemberRepository


class LibraryService:
    def __init__(self, database: Database) -> None:
        self.database = database
        connection = database.connection
        self.books = BookRepository(connection)
        self.authors = AuthorRepository(connection)
        self.members = MemberRepository(connection)
        self.loans = LoanRepository(connection)

    def add_book(self, book: Book) -> Book:
        return self.books.create(book)

    def add_author(self, author: Author) -> Author:
        return self.authors.create(author)

    def add_member(self, member: Member) -> Member:
        return self.members.create(member)

    def borrow_book(self, member_id: int, book_id: int) -> Loan:
        """Create a 14-day loan and decrement stock atomically."""
        with self.database.transaction():
            member = self.members.get(member_id)
            if not member.is_active:
                raise InactiveMemberError(f"Member {member_id} is inactive")
            book = self.books.get(book_id)
            if book.available_copies <= 0:
                raise BookNotAvailableError(f"Book {book_id} has no available copies")
            loan_day = date.today()
            loan = self.loans.create(
                Loan(book_id=book_id, member_id=member_id, loan_date=loan_day, due_date=loan_day + timedelta(days=14))
            )
            self.books.adjust_available_copies(book_id, -1)
            return loan

    def return_book(self, loan_id: int) -> Loan:
        """Return a loan and restore one copy atomically, including late loans."""
        with self.database.transaction():
            loan = self.loans.get(loan_id)
            if loan.return_date is not None or loan.status == "returned":
                raise AlreadyReturnedLoanError(f"Loan {loan_id} has already been returned")
            updated = Loan(
                id=loan.id, book_id=loan.book_id, member_id=loan.member_id,
                loan_date=loan.loan_date, due_date=loan.due_date,
                return_date=date.today(), status="returned",
            )
            saved = self.loans.update(updated)
            self.books.adjust_available_copies(loan.book_id, 1)
            return saved

    def get_overdue_loans(self) -> list[Loan]:
        return self.loans.find_overdue_loans()

    def renew_membership(self, member_id: int) -> Member:
        member = self.members.get(member_id)
        member.is_active = not member.is_active
        return self.members.update(member)

    def search_books(self, query: str) -> list[Book]:
        return self.books.search(query)
