"""SQLite repositories: persistence only, with no business policy."""

import sqlite3

from .models import StorageLocation, Wine, WineType


def _wine(row: sqlite3.Row) -> Wine:
    return Wine(
        id=row["id"], name=row["name"], vintage_year=row["vintage_year"],
        wine_type=WineType(row["wine_type"]), country=row["country"],
        cost_price=row["cost_price"], selling_price=row["selling_price"],
        stock_quantity=row["stock_quantity"], location_id=row["location_id"],
    )


class WineRepository:
    def list(self, connection: sqlite3.Connection) -> list[Wine]:
        rows = connection.execute("SELECT * FROM wines ORDER BY name COLLATE NOCASE").fetchall()
        return [_wine(row) for row in rows]

    def get(self, connection: sqlite3.Connection, wine_id: int) -> Wine | None:
        row = connection.execute("SELECT * FROM wines WHERE id = ?", (wine_id,)).fetchone()
        return _wine(row) if row else None

    def name_exists(self, connection: sqlite3.Connection, name: str, except_id: int | None = None) -> bool:
        query = "SELECT 1 FROM wines WHERE name = ? COLLATE NOCASE"
        params: tuple[object, ...] = (name,)
        if except_id is not None:
            query += " AND id != ?"
            params += (except_id,)
        return connection.execute(query, params).fetchone() is not None

    def assigned_bottles(self, connection: sqlite3.Connection, location_id: int, except_wine_id: int | None = None) -> int:
        query = "SELECT COALESCE(SUM(stock_quantity), 0) FROM wines WHERE location_id = ?"
        params: tuple[object, ...] = (location_id,)
        if except_wine_id is not None:
            query += " AND id != ?"
            params += (except_wine_id,)
        return int(connection.execute(query, params).fetchone()[0])

    def save(self, connection: sqlite3.Connection, wine: Wine) -> Wine:
        if wine.id:
            connection.execute(
                """UPDATE wines SET name=?, vintage_year=?, wine_type=?, country=?, cost_price=?,
                   selling_price=?, stock_quantity=?, location_id=? WHERE id=?""",
                (wine.name, wine.vintage_year, wine.wine_type.value, wine.country, wine.cost_price,
                 wine.selling_price, wine.stock_quantity, wine.location_id, wine.id),
            )
            wine_id = wine.id
        else:
            cursor = connection.execute(
                """INSERT INTO wines(name, vintage_year, wine_type, country, cost_price,
                   selling_price, stock_quantity, location_id) VALUES (?, ?, ?, ?, ?, ?, ?, ?)""",
                (wine.name, wine.vintage_year, wine.wine_type.value, wine.country, wine.cost_price,
                 wine.selling_price, wine.stock_quantity, wine.location_id),
            )
            wine_id = int(cursor.lastrowid)
        return self.get(connection, wine_id)  # type: ignore[return-value]


class LocationRepository:
    def list(self, connection: sqlite3.Connection) -> list[StorageLocation]:
        rows = connection.execute(
            """SELECT l.*, COALESCE(SUM(w.stock_quantity), 0) AS bottle_count
               FROM storage_locations l LEFT JOIN wines w ON w.location_id=l.id
               GROUP BY l.id ORDER BY l.zone_name COLLATE NOCASE, l.row_number, l.shelf_number"""
        ).fetchall()
        return [StorageLocation(row["id"], row["zone_name"], row["row_number"],
                                row["shelf_number"], row["max_capacity"], row["bottle_count"])
                for row in rows]

    def get(self, connection: sqlite3.Connection, location_id: int) -> StorageLocation | None:
        row = connection.execute("SELECT * FROM storage_locations WHERE id=?", (location_id,)).fetchone()
        if row is None:
            return None
        count = connection.execute(
            "SELECT COALESCE(SUM(stock_quantity),0) FROM wines WHERE location_id=?", (location_id,)
        ).fetchone()[0]
        return StorageLocation(row["id"], row["zone_name"], row["row_number"],
                               row["shelf_number"], row["max_capacity"], int(count))

    def exists(self, connection: sqlite3.Connection, location_id: int) -> bool:
        return connection.execute("SELECT 1 FROM storage_locations WHERE id=?", (location_id,)).fetchone() is not None

    def assigned_wines(self, connection: sqlite3.Connection, location_id: int) -> int:
        return int(connection.execute("SELECT COUNT(*) FROM wines WHERE location_id=?", (location_id,)).fetchone()[0])

    def save(self, connection: sqlite3.Connection, location: StorageLocation) -> StorageLocation:
        if location.id:
            connection.execute(
                "UPDATE storage_locations SET zone_name=?, row_number=?, shelf_number=?, max_capacity=? WHERE id=?",
                (location.zone_name, location.row_number, location.shelf_number, location.max_capacity, location.id),
            )
            location_id = location.id
        else:
            cursor = connection.execute(
                "INSERT INTO storage_locations(zone_name,row_number,shelf_number,max_capacity) VALUES(?,?,?,?)",
                (location.zone_name, location.row_number, location.shelf_number, location.max_capacity),
            )
            location_id = int(cursor.lastrowid)
        return self.get(connection, location_id)  # type: ignore[return-value]

    def delete(self, connection: sqlite3.Connection, location_id: int) -> None:
        connection.execute("DELETE FROM storage_locations WHERE id=?", (location_id,))
