"""Application services and business-rule enforcement."""

import math
import sqlite3

from .database import Database
from .exceptions import (
    DuplicateWineNameError, InvalidPricingException, LocationInUseError,
    LocationOverCapacityException, NegativeStockError, NotFoundError, ValidationError,
)
from .models import StorageLocation, Wine, WineType
from .repositories import LocationRepository, WineRepository


def _text(value: str, label: str) -> str:
    result = value.strip()
    if not result:
        raise ValidationError(f"{label} is required.")
    return result


def _positive_integer(value: int, label: str) -> int:
    if isinstance(value, bool) or not isinstance(value, int) or value <= 0:
        raise ValidationError(f"{label} must be a positive whole number.")
    return value


def _money(value: float, label: str) -> float:
    try:
        amount = float(value)
    except (TypeError, ValueError) as error:
        raise ValidationError(f"{label} must be a valid amount.") from error
    if not math.isfinite(amount) or amount < 0:
        raise ValidationError(f"{label} must be a finite, non-negative amount.")
    return round(amount, 2)


class WineService:
    def __init__(self, database: Database, wines: WineRepository, locations: LocationRepository) -> None:
        self.database, self.wines, self.locations = database, wines, locations

    def list_wines(self) -> list[Wine]:
        with self.database.read() as connection:
            return self.wines.list(connection)

    def save_wine(self, *, wine_id: int = 0, name: str, vintage_year: int, wine_type: WineType | str,
                  country: str, cost_price: float, selling_price: float, stock_quantity: int,
                  location_id: int) -> Wine:
        clean_name, clean_country = _text(name, "Wine name"), _text(country, "Country")
        if isinstance(vintage_year, bool) or not isinstance(vintage_year, int):
            raise ValidationError("Vintage year must be a whole number.")
        try:
            kind = WineType(wine_type)
        except ValueError as error:
            raise ValidationError("Choose red, white, rosé, or sparkling wine.") from error
        cost, selling = _money(cost_price, "Cost price"), _money(selling_price, "Selling price")
        if selling <= cost:
            raise InvalidPricingException("Selling price must be greater than cost price.")
        if isinstance(stock_quantity, bool) or not isinstance(stock_quantity, int):
            raise ValidationError("Stock quantity must be a whole number.")
        if stock_quantity < 0:
            raise NegativeStockError("Stock quantity cannot be below zero.")
        if isinstance(location_id, bool) or not isinstance(location_id, int) or location_id <= 0:
            raise ValidationError("Select a storage location.")
        with self.database.transaction() as connection:
            existing = self.wines.get(connection, wine_id) if wine_id else None
            if wine_id and existing is None:
                raise NotFoundError("Wine not found.")
            if self.wines.name_exists(connection, clean_name, wine_id or None):
                raise DuplicateWineNameError(f'A wine named "{clean_name}" already exists.')
            if not self.locations.exists(connection, location_id):
                raise NotFoundError("Storage location not found.")
            location = self.locations.get(connection, location_id)
            assigned = self.wines.assigned_bottles(connection, location_id, wine_id or None)
            if assigned + stock_quantity > location.max_capacity:
                raise LocationOverCapacityException(
                    f"{location.display_name} holds {assigned} bottles and has capacity {location.max_capacity}."
                )
            wine = Wine(wine_id, clean_name, vintage_year, kind, clean_country, cost, selling,
                        stock_quantity, location_id)
            try:
                return self.wines.save(connection, wine)
            except sqlite3.IntegrityError as error:
                if "wines.name" in str(error).lower() or "unique constraint failed: wines.name" in str(error).lower():
                    raise DuplicateWineNameError(f'A wine named "{clean_name}" already exists.') from error
                raise


class LocationService:
    def __init__(self, database: Database, locations: LocationRepository, wines: WineRepository) -> None:
        self.database, self.locations, self.wines = database, locations, wines

    def list_locations(self) -> list[StorageLocation]:
        with self.database.read() as connection:
            return self.locations.list(connection)

    def save_location(self, *, location_id: int = 0, zone_name: str, row_number: int,
                      shelf_number: int, max_capacity: int) -> StorageLocation:
        zone = _text(zone_name, "Zone name")
        row, shelf = _positive_integer(row_number, "Row number"), _positive_integer(shelf_number, "Shelf number")
        capacity = _positive_integer(max_capacity, "Bottle capacity")
        with self.database.transaction() as connection:
            if location_id and not self.locations.exists(connection, location_id):
                raise NotFoundError("Storage location not found.")
            used = self.wines.assigned_bottles(connection, location_id) if location_id else 0
            if capacity < used:
                raise LocationOverCapacityException(f"This location already contains {used} bottles.")
            try:
                return self.locations.save(connection, StorageLocation(
                    location_id, zone, row, shelf, capacity, used
                ))
            except sqlite3.IntegrityError as error:
                raise ValidationError("That zone, row, and shelf combination already exists.") from error

    def remove_location(self, location_id: int) -> None:
        with self.database.transaction() as connection:
            if not self.locations.exists(connection, location_id):
                raise NotFoundError("Storage location not found.")
            if self.locations.assigned_wines(connection, location_id):
                raise LocationInUseError("This location cannot be removed while wines are assigned to it.")
            self.locations.delete(connection, location_id)


class InventoryService:
    """Convenience facade sharing repositories across the application services."""

    def __init__(self, database: Database) -> None:
        wines, locations = WineRepository(), LocationRepository()
        self.wines = WineService(database, wines, locations)
        self.locations = LocationService(database, locations, wines)
