class InventoryServiceTests(unittest.TestCase):
    def setUp(self):
        self.temp_dir = tempfile.TemporaryDirectory()
        self.service = InventoryService(Database(Path(self.temp_dir.name) / "test.sqlite3"))
        self.location = self.service.locations.save_location(
            zone_name="Main Cellar", row_number=1, shelf_number=3, max_capacity=5
        )

    def tearDown(self):
        self.temp_dir.cleanup()

    def add_wine(self, **overrides):
        values = dict(name="Estate Red", vintage_year=2019, wine_type=WineType.RED,
                      country="France", cost_price=20, selling_price=35,
                      stock_quantity=2, location_id=self.location.id)
        values.update(overrides)
        return self.service.wines.save_wine(**values)

    def test_persists_and_enforces_capacity(self):
        wine = self.add_wine()
        self.assertEqual(self.service.wines.list_wines()[0], wine)
        with self.assertRaises(LocationOverCapacityException):
            self.add_wine(name="Too Many", stock_quantity=4)

    def test_business_constraints(self):
        self.add_wine()
        with self.assertRaises(DuplicateWineNameError):
            self.add_wine(name="estate red")
        with self.assertRaises(NegativeStockError):
            self.add_wine(name="Negative", stock_quantity=-1)
        with self.assertRaises(InvalidPricingException):
            self.add_wine(name="Bad Price", selling_price=20)
        with self.assertRaises(LocationInUseError):
            self.service.locations.remove_location(self.location.id)

    def test_capacity_cannot_be_reduced_below_stock(self):
        self.add_wine()
        with self.assertRaises(LocationOverCapacityException):
            self.service.locations.save_location(location_id=self.location.id,
                zone_name="Main Cellar", row_number=1, shelf_number=3, max_capacity=1)


