    unittest.main()

#!/usr/bin/env python3
"""Convert a CSV file into a JSON array of row objects."""

import argparse
import csv
import json
import sys
from pathlib import Path


class CSVInputError(Exception):
    """Raised when the input is not a well-formed CSV table."""


def read_csv(input_path: Path) -> list[dict[str, str]]:
    """Read CSV rows using the first record as the dynamic object keys."""
    try:
        with input_path.open("r", encoding="utf-8-sig", newline="") as source:
            reader = csv.reader(source, strict=True)
            try:
                headers = next(reader)
            except StopIteration:
                raise CSVInputError("input CSV is empty; expected a header row") from None

            if len(headers) != len(set(headers)):
                raise CSVInputError("header row contains duplicate column names")

            objects: list[dict[str, str]] = []
            for row in reader:
                # Match DictReader's conventional treatment of blank lines.
                if not row:
                    continue
                if len(row) != len(headers):
                    raise CSVInputError(
                        f"malformed CSV at line {reader.line_num}: expected "
                        f"{len(headers)} fields, found {len(row)}"
                    )
                objects.append(dict(zip(headers, row)))
            return objects
    except csv.Error as exc:
        raise CSVInputError(f"malformed CSV near line {getattr(reader, 'line_num', '?')}: {exc}") from exc
    except UnicodeDecodeError as exc:
        raise CSVInputError(f"input is not valid UTF-8: {exc}") from exc
    except OSError as exc:
        raise CSVInputError(str(exc)) from exc


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(
        description="Convert a CSV file to a JSON array of objects."
    )
    parser.add_argument("input", type=Path, help="path to the input CSV file")
    parser.add_argument(
        "output",
        type=Path,
        nargs="?",
        help="optional path for the JSON output (defaults to stdout)",
    )
    args = parser.parse_args(argv)

    try:
        records = read_csv(args.input)
        rendered = json.dumps(records, ensure_ascii=False, indent=2) + "\n"
        if args.output is None:
            sys.stdout.write(rendered)
        else:
            args.output.write_text(rendered, encoding="utf-8")
    except (CSVInputError, OSError) as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

