import json,os
base='$BASE'
for p in ['prompt_03','prompt_13','prompt_18','prompt_19','prompt_26','prompt_32','prompt_34','prompt_40','prompt_41','prompt_60']:
 print('\n'+'='*80); print(p)
 d=os.path.join(base,p)
 for name in ['data_models.json','components.json','service_contracts.json','persistence_ports.json']:
  path=os.path.join(d,name)
  if not os.path.exists(path): print(name,'MISSING'); continue
  obj=json.load(open(path))
  if name=='data_models.json':
   print('models:',[(m.get('name'),[(f.get('name'),f.get('type'),f.get('foreign_key')) for f in m.get('fields',[])]) for m in obj.get('data_models',[])])
  elif name=='components.json':
   comps=obj.get('components',{}); print('persistence:',comps.get('persistence')); print('crud_services:',comps.get('crud_services'))
   inv=(comps.get('facade') or {}).get('invocation') or {}
   print('commands:',[(c.get('name'),[s.get('name') for s in c.get('subcommands',[])]) for c in inv.get('commands',[])])
  elif name=='service_contracts.json':
   for s in obj.get('service_contracts',[]): print('service',s.get('service_name'),'methods',[(m.get('name'),m.get('raises')) for m in s.get('methods',[])])
  else:
   print('repos:',[(r.get('entity'),r.get('interface_name')) for r in obj.get('repositories',[])])
PY

