    for item in subcommands:
        if isinstance(item, dict) and normalize(item.get("name") or "") == normalize(sub):
            return
    subcommands.append({"name": sub, "options": []})
    if log is not None:
        log.write(f"[ok] step components: added '{command} {sub}' the requirements name")


