    if kind == "DIRECT" or value is None:
        return value
    if kind == "ISO_DATE":
        return datetime.date.fromisoformat(str(value))
    if kind == "DECIMAL_TO_CENTS":
        return int(round(float(value) * 100))
    if kind == "CSV_LIST":
        items = value if isinstance(value, (list, tuple)) else [value]
        split = []
        for part in items:
