"""Services. A method with the same name as a repository method delegates
to it; anything else raises NotImplementedError with its work order.
"""

from __future__ import annotations

from typing import Any, Dict, List, Optional, Tuple, Union

import calendar
import csv
import datetime
import json

import models
import errors
from store import match_criterion


def _holds(actual, operator, expected):
    """Twin of `store._holds`: the operators filter composition reuses."""
    if operator == "eq":
        return actual == expected
    if operator == "ge":
        return actual is not None and actual >= expected
    if operator == "le":
        return actual is not None and actual <= expected
    if operator == "gt":
        return actual is not None and actual > expected
    if operator == "lt":
        return actual is not None and actual < expected
    raise ValueError(f"unknown operator {operator!r}")


def _as_date(value):
    """Accept an ISO string or a date object; return a date or None."""
    if value is None or isinstance(value, datetime.date):
        return value
    return datetime.date.fromisoformat(str(value))



class TaskRepository:

    def __init__(self, repos):
        self._repos = repos


    def create(self, description: str = None, is_completed: bool = None) -> models.Task:
        """Creates a new Task. [no same-name repository method to delegate to]"""
        raise NotImplementedError(
            "TaskRepository.create: STANDARD_CRUD")

    def read_all(self, description: str = None, is_completed: bool = None) -> list[models.Task]:
        """Lists every Task; optional fields narrow the result. [no same-name repository method to delegate to]"""
        raise NotImplementedError(
            "TaskRepository.read_all: FILTER_BY_FIELD")

    def update(self, id: int = None, description: str = None, is_completed: bool = None) -> models.Task:
        """Updates an existing Task. [no same-name repository method to delegate to]"""
        raise NotImplementedError(
            "TaskRepository.update: STANDARD_CRUD")

    def delete(self, id: int = None, description: str = None, is_completed: bool = None) -> None:
        """Deletes an existing Task. [no same-name repository method to delegate to]"""
        raise NotImplementedError(
            "TaskRepository.delete: STANDARD_CRUD")
