class OrderService:

    def __init__(self, repos):
        self._repos = repos


    def confirm_order(self, order_id: UUID = None) -> None:
        """Transitions an order from pending to confirmed state. Requires the order to be in pending state. Cannot confirm a confirmed or shipped order. [closed contract: closed scalar contract]"""
        order = self._repos['OrderRepository'].read_one(order_id)
        if not (order.state == 'pending'):
            raise errors.OrderStateException("order.state == 'pending'")
        self._repos['OrderRepository'].update(order.id, state='confirmed')

    def ship_order(self, order_id: UUID = None) -> None:
        """Transitions an order from confirmed to shipped state. Requires the order to be in confirmed state. Cannot ship a pending or cancelled order. [closed contract: closed scalar contract]"""
        order = self._repos['OrderRepository'].read_one(order_id)
        if not (order.state == 'confirmed'):
            raise errors.OrderStateException("order.state == 'confirmed'")
        self._repos['OrderRepository'].update(order.id, state='shipped')

    def cancel_order(self, order_id: UUID = None) -> None:
        """Transitions an order from pending or confirmed to cancelled state. Cannot cancel a shipped order. After cancellation, the order cannot be shipped. [closed contract: closed scalar contract]"""
        order = self._repos['OrderRepository'].read_one(order_id)
        if not (order.state in ('pending', 'confirmed')):
            raise errors.OrderStateException("order.state in ('pending', 'confirmed')")
        self._repos['OrderRepository'].update(order.id, state='cancelled')

    def read_order_by_id(self, id: int = None) -> models.Order | None:
