    def place_order(self, customer_id: str = None, order_items: Any = None) -> models.Order:
        """Places an order for a customer with specified products and quantities. Validates that all products have sufficient stock. If valid, reserves stock and creates the order. [llm-written by server — review]"""
        customer = self._repos['CustomerRepository'].read_one(id=int(customer_id))
        if not customer:
            raise errors.CustomerNotFoundError(f'Customer with id {customer_id} not found')
        order_items_list = order_items or []
        for item in order_items_list:
            product_id = item.get('product_id')
            quantity = item.get('quantity')
            if not product_id or not quantity:
                raise ValueError('Product ID and quantity are required for each order item')
            product = self._repos['ProductRepository'].read_one(id=int(product_id))
            if not product:
                raise errors.ProductNotFoundError(f'Product with id {product_id} not found')
            if product.stock_quantity is None or product.stock_quantity < quantity:
                raise errors.InsufficientStockError(f'Insufficient stock for product {product_id}: requested {quantity}, available {product.stock_quantity}')
            product.stock_quantity -= quantity
            self._repos['ProductRepository'].update(id=product.id, stock_quantity=product.stock_quantity)
        order_date = datetime.datetime.now()
        order = self._repos['OrderRepository'].create(customer_id=int(customer_id), order_date=order_date)
        return order


def _atomic(method):
    """Run a multi-write service method in one store transaction."""
    def wrapper(self, *args, **kwargs):
        store = None
        for repo in self._repos.values():
            store = getattr(repo, '_store', None)
            if store is not None:
                break
        if store is None or not hasattr(store, 'transaction'):
            return method(self, *args, **kwargs)
        with store.transaction():
            return method(self, *args, **kwargs)
    wrapper.__name__ = method.__name__
    wrapper.__doc__ = method.__doc__
    wrapper.__wrapped__ = method
    return wrapper


