            continue
        match = re.match(rf"{prefix}\s+in\s*\(([^)]*)\)", check)
        if match:
            raw = match.group(2)
            items = re.findall(r"['\"](.*?)['\"]", raw)
            if items:
                values[match.group(1)] = items[0]
