                          record.get("subcommand"))
        if not isinstance(leaf, dict):
            continue
        for option in leaf.get("options") or []:
            if codegen.option_dest(option) != flag:
                continue
            if option.get("type") != option_type:
                option["type"] = option_type
                option["required"] = False
