            "create", "update", "delete"):
        return None
    returns = method.get("return_type") or ""
    words = {normalize(token) for token in
             re.findall(r"[A-Za-z_][A-Za-z0-9_]*", returns)}
    if normalize(entity) not in words or "list" in words:
        return None
