"""Schema invariants derived from the data model, without a model call.

Step C used to ask the small model for both business rules and field-level
facts: a field's type, nullability, uniqueness, primary key, foreign key,
default and allowed values. Those facts are already in `data_models.json`;
asking for them again spends output tokens and lets the model contradict the
model it is supposed to describe.

`SCHEMA` text is the kind the collector already skips in step F, so these
entries cost nothing downstream. The model keeps the part only it can write:
rules relating fields, aggregates, states and operations.
"""

import re

_TYPE_WORDS = {
    "int": "integer",
    "integer": "integer",
    "float": "number",
    "double": "number",
    "decimal": "number",
    "str": "string",
    "string": "string",
    "text": "string",
    "bool": "boolean",
    "boolean": "boolean",
    "date": "date",
    "datetime": "datetime",
    "timestamp": "datetime",
}


def _field_names(entity):
    return [field.get("name") for field in entity.get("fields") or []
            if isinstance(field, dict) and isinstance(field.get("name"), str)]


def _composite_groups(entity, requirements):
    """Composite unique keys named by the requirements for one entity."""
    names = {name.lower() for name in _field_names(entity)}
    if len(names) < 2 or not isinstance(requirements, str):
        return []
    groups = []

    def add(tokens):
        resolved = []
        for token in tokens:
            lowered = str(token).lower()
            if lowered in names and lowered not in resolved:
                resolved.append(lowered)
        if len(resolved) >= 2 and tuple(resolved) not in groups:
            groups.append(tuple(resolved))

    for match in re.finditer(r"UNIQUE\s*\(([^)]*)\)", requirements, re.I):
        add(re.findall(r"[A-Za-z_][A-Za-z0-9_]*", match.group(1)))
    for match in re.finditer(
            r"unique\s+(?:constraint\s+)?(?:on|over|for)\s*\(([^)]*)\)",
            requirements, re.I):
        add(re.findall(r"[A-Za-z_][A-Za-z0-9_]*", match.group(1)))
    for match in re.finditer(
            r"([A-Za-z_][A-Za-z0-9_]*(?:\s*(?:,|and)\s*[A-Za-z_][A-Za-z0-9_]*)+)"
            r"\s+must\s+be\s+unique\s+together", requirements, re.I):
        add(re.findall(r"[A-Za-z_][A-Za-z0-9_]*", match.group(1)))
    return [tuple(name for name in group) for group in groups]



def _enum_values(field_name, requirements):
    """The slash/`one of` vocabulary a requirement gives one field, or []."""
    if not isinstance(requirements, str):
        return []
    field = re.escape(field_name)
    match = re.search(rf"\b{field}\b\s*\(([^)]*/[^)]*)\)", requirements, re.I)
    if match:
        return [value.strip(" `'\"") for value in match.group(1).split("/")
                if value.strip(" `'\"")]
    match = re.search(
        rf"\b{field}\b[^.\n]*?must be one of\s*([^.\n]+)", requirements, re.I)
    if match:
        values = re.findall(r"['\"]([^'\"]+)['\"]", match.group(1))
        if values:
            return values
    return []

def _numeric_bound(entity_name, field_name, requirements):
    """`(word, value)` for a documented non-negative/positive bound, or None.

    A negated predicate is never read as its positive form. In particular
    "must not be positive" has no mechanical non-negative bound; leaving it
    unresolved is safer than emitting the opposite invariant.
    """
    if not isinstance(requirements, str):
        return None
    field = re.escape(field_name)
    match = re.search(rf"\b{field}\b([^.\n]*)", requirements, re.I)
    if match is None:
        return None
    tail = match.group(1)
    if re.search(r"\bnot\s+(?:be\s+)?positive\b", tail, re.I) \
            or re.search(r"\bnot\s+(?:be\s+)?non-?negative\b", tail, re.I):
        return None
    if re.search(r"\bnon-negative\b", tail, re.I) \
            or re.search(r"\bnot\s+(?:be\s+)?negative\b", tail, re.I) \
            or re.search(r"\b(?:below|under)\s+zero\b", tail, re.I):
        return ("non-negative", "0")
    if re.search(r"\bpositive\b", tail, re.I) \
            and not re.search(r"\b(?:not|never|no)\b[^.\n]*?\bpositive\b",
                              tail, re.I):
        return ("positive", "1")
    if re.search(r"(?<!not\s)(?<!not\sbe\s)>=\s*0\b", tail, re.I):
        return (">=", "0")
    if re.search(r"(?<!not\s)(?<!not\sbe\s)>\s*0\b", tail, re.I):
        return (">", "0")
    return None


def schema_invariants(documents, requirements=""):
    """`[{text, kind: 'schema'}]` derived from the data models."""
    entries = []
    seen = set()

    def add(text):
        key = " ".join(text.lower().split())
        if key not in seen:
            seen.add(key)
            entries.append({"text": text, "kind": "schema"})

    for entity in documents.get("data_models") or []:
        if not isinstance(entity, dict):
            continue
        entity_name = entity.get("name")
        if not isinstance(entity_name, str) or not entity_name.strip():
            continue
        fields = [field for field in entity.get("fields") or []
                  if isinstance(field, dict) and field.get("name")]
        for field in fields:
            name = field["name"]
            declared = str(field.get("type") or "").strip().lower()
            type_word = _TYPE_WORDS.get(declared)
            if field.get("primary_key"):
                add(f"{entity_name}.{name} must be an auto-incremented "
                    f"integer primary key with default value None")
            elif type_word:
                article = "an" if type_word[0] in "aeiou" else "a"
                add(f"{entity_name}.{name} must be {article} {type_word}")
            if not field.get("primary_key") and field.get("nullable") is False:
                add(f"{entity_name}.{name} must not be null")
            if not field.get("primary_key") and field.get("unique"):
                add(f"{entity_name}.{name} must be unique")
            enum_values = _enum_values(name, requirements)
            if enum_values:
                add(f"{entity_name}.{name} must be one of "
                    + ", ".join(repr(value) for value in enum_values))
            foreign = field.get("foreign_key")
            if isinstance(foreign, dict) and foreign.get("target_entity"):
                target = foreign["target_entity"]
                target_field = foreign.get("target_field") or "id"
                add(f"{entity_name}.{name} must reference an existing "
                    f"{target}.{target_field}")
            if field.get("default") is not None and not field.get("primary_key"):
                add(f"{entity_name}.{name} must default to {field['default']}")
            bound = _numeric_bound(entity_name, name, requirements)
            if bound is not None:
                word, value = bound
                if word in (">=", ">"):
                    add(f"{entity_name}.{name} must be {word} {value}")
                else:
                    add(f"{entity_name}.{name} must be {word}")

        for group in _composite_groups(entity, requirements):
            add(f"{entity_name} must have a unique constraint on "
                f"({', '.join(group)})")
    return entries


def merge_invariants(schema, rules):
    """Schema first, then the model's rules, with exact duplicates removed."""
    merged = []
    seen = set()
    for item in list(schema) + list(rules or []):
        if not isinstance(item, dict):
            continue
        text = item.get("text")
        if not isinstance(text, str) or not text.strip():
            continue
        key = " ".join(text.lower().split())
        if key in seen:
            continue
        seen.add(key)
        merged.append({"text": text.strip(),
                       "kind": item.get("kind") if item.get("kind") in
                       ("schema", "rule") else "rule"})
    return merged

#!/usr/bin/env python3
"""Ask about a flag that several service methods could satisfy.

`repair_missing_method_flags` can type a missing flag only when exactly one
method/parameter pair matches it. When several methods match, the choice
changes the operation and the flag's type; this review asks for the chosen
service, method, parameter and option type and records them in
`flag_decisions.json`.
"""

from __future__ import annotations

import argparse
import json
import re
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent
sys.path.insert(0, str(ROOT))

import generator  # noqa: E402
from kernel.consistency import checks_surface as surface_checks  # noqa: E402
from kernel.consistency.naming import normalize  # noqa: E402
from kernel.extraction import repairs  # noqa: E402
from kernel.extraction.decisions import requirements_sha  # noqa: E402


def _decisions(directory):
    return repairs.load_flag_decisions(str(directory))


def _candidates(services, flag):
    found = []
    for service in services or []:
        if not isinstance(service, dict):
            continue
        for method in service.get("methods") or []:
            if not isinstance(method, dict) or not method.get("name"):
                continue
            if normalize(flag) not in normalize(method["name"]):
                continue
            for param in method.get("params") or []:
                if (isinstance(param, dict)
                        and normalize(param.get("name") or "") == normalize(flag)):
                    found.append({
                        "service": service.get("service_name"),
                        "method": method.get("name"),
                        "param": param.get("name"),
                        "type": param.get("type"),
                        "option_type": repairs._option_type(param.get("type")),
                    })
    return found


def _covered(decisions, command, sub, flag, candidates):
    for record in decisions:
        if (normalize(record.get("command") or "") != normalize(command)
                or normalize(record.get("subcommand") or "") != normalize(sub or "")
                or normalize(record.get("flag") or "") != normalize(flag)):
            continue
        for candidate in candidates:
            if (normalize(candidate["service"]) == normalize(record.get("service") or "")
                    and normalize(candidate["method"]) == normalize(record.get("method") or "")
                    and normalize(candidate["param"]) == normalize(record.get("param") or "")):
                return True
    return False


def collect_questions(output_dir):
    """`(questions, context)` for ambiguous missing flags."""
    directory = Path(output_dir)
    ctx = generator.load_context(str(directory))
    requirements = (directory / "requirements.txt").read_text(encoding="utf-8") \
        if (directory / "requirements.txt").is_file() else ""
    if not requirements:
        return [], {"requirements_sha": requirements_sha("")}
    facade = ctx.get("components", {}).get("facade") or {}
    invocation = facade.get("invocation") if isinstance(facade, dict) else None
    if not isinstance(invocation, dict):
        return [], {"requirements_sha": requirements_sha(requirements)}
    commands = surface_checks._commands_by_name(invocation)
    program = surface_checks._program_name(requirements)
    decisions = _decisions(directory)
    questions = []
    for span in re.findall(r"`([^`]*)`", requirements):
        target = surface_checks._resolve_span(span, program, commands)
        if target is None:
            continue
        command, sub = target
        leaf = repairs._find_leaf(invocation, command, sub)
        if leaf is None:
            continue
        for flag, bracketed in surface_checks._flags_in(span):
            if repairs._leaf_has_flag(leaf, flag):
                continue
            candidates = _candidates(ctx.get("services") or [], flag)
            if len(candidates) <= 1 or _covered(
                    decisions, command, sub, flag, candidates):
                continue
            questions.append({
                "command": command,
                "subcommand": sub,
                "flag": flag,
                "bracketed": bracketed,
                "source": span,
                "candidates": candidates,
                "requirements_sha": requirements_sha(requirements),
            })
    return questions, {"requirements_sha": requirements_sha(requirements)}


def describe_question(index, total, question):
    lines = [
        f"--- flag question {index}/{total} ---",
        f"source: {question.get('source')}",
        f"missing: --{question.get('flag')}",
        "candidates:",
    ]
    for number, candidate in enumerate(question.get("candidates") or [], start=1):
        lines.append(
            f"  {number}) {candidate.get('service')}."
            f"{candidate.get('method')}({candidate.get('param')}: "
            f"{candidate.get('type')}) -> {candidate.get('option_type')}")
    return lines


def ask(question, input_fn=input):
    candidates = question.get("candidates") or []
    try:
        answer = input_fn("choose a candidate number, or skip: ").strip()
    except (EOFError, KeyboardInterrupt):
        return None
    if answer.lower() in ("", "skip", "s"):
        return None
    try:
        index = int(answer) - 1
    except ValueError:
        return None
    return candidates[index] if 0 <= index < len(candidates) else None


def run_review(output_dir, input_fn=input, out_fn=print):
    questions, context = collect_questions(output_dir)
    if not questions:
        out_fn("no ambiguous method-backed flags — nothing to decide")
        return 0, 0
    records = _decisions(output_dir)
    answered = 0
    for number, question in enumerate(questions, start=1):
        for line in describe_question(number, len(questions), question):
            out_fn(line)
        chosen = ask(question, input_fn)
        if chosen is None:
            out_fn("skipped — left open")
            continue
        record = {
            "command": question["command"],
            "subcommand": question["subcommand"],
            "flag": question["flag"],
            "service": chosen["service"],
            "method": chosen["method"],
            "param": chosen["param"],
            "option_type": chosen["option_type"],
            "decided_by": "user",
            "requirements_sha": context["requirements_sha"],
        }
        records = [item for item in records
                   if not (normalize(item.get("command") or "") == normalize(record["command"])
                           and normalize(item.get("subcommand") or "") == normalize(record["subcommand"] or "")
                           and normalize(item.get("flag") or "") == normalize(record["flag"]))]
        records.append(record)
        answered += 1
    repairs.save_flag_decisions(str(output_dir), records)
    out_fn(f"answered {answered} of {len(questions)}; decisions in "
           f"{repairs.FLAG_DECISIONS_NAME}")
    return len(questions), answered


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("output_dir")
    args = parser.parse_args(argv)
    questions, _context = collect_questions(args.output_dir)
    if not questions:
        print("no ambiguous method-backed flags — nothing to decide")
        return 0
    input_fn = input
    run_review(args.output_dir, input_fn=input_fn)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
#!/usr/bin/env python3
"""Report service methods with no evidence in the requirements/intentions.

This is a review check, not a mutating generator step.  It writes a report;
the reviewed drops go in ``grounding_decisions.json`` and the generator applies
them before adapters/commands are emitted.

Usage:
    python review_grounding.py out/60_program_clean
    python review_grounding.py out/60_program_clean --write-report
"""

import argparse
import json
import os
import re
import sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

from kernel.extraction import grounding  # noqa: E402
from kernel.extraction.decisions import requirements_sha  # noqa: E402


def _read(path, default):
    try:
        with open(path, encoding="utf-8") as handle:
            return json.load(handle)
    except (OSError, ValueError):
        return default


def _effective_services(out_dir, services):
    decisions = _read(os.path.join(out_dir, "grounding_decisions.json"), {})
    drop_services = {grounding._flat(name) for name in
                     decisions.get("drop_services") or []}
    drop_methods = {(grounding._flat(item.get("holder") or ""),
                     grounding._flat(item.get("method") or ""))
                    for item in decisions.get("drop_methods") or []
                    if isinstance(item, dict)}
    effective = []
    for service in services:
        holder = grounding._flat(service.get("service_name") or "")
        if holder in drop_services:
            continue
        methods = [method for method in service.get("methods") or []
                   if isinstance(method, dict)
                   and (holder, grounding._flat(method.get("name") or ""))
                   not in drop_methods]
        if methods:
            service = dict(service)
            service["methods"] = methods
            effective.append(service)
    return effective, decisions


def _build_report(out_dir):
    requirements_path = os.path.join(out_dir, "requirements.txt")
    try:
        with open(requirements_path, encoding="utf-8") as handle:
            requirements = handle.read()
    except OSError:
        return None, None, None
    intentions = _read(os.path.join(out_dir, "intentions.json"), {})
    if isinstance(intentions, dict):
        intentions = intentions.get("intentions") or []
    services = _read(os.path.join(out_dir, "service_contracts.json"), {})
    if isinstance(services, dict):
        services = services.get("service_contracts") or []
    effective, decisions = _effective_services(out_dir, services)
    report = grounding.report(requirements, intentions, effective)
    aggregates = _read(os.path.join(out_dir, "aggregate_decisions.json"), {})
    aggregate_keys = {
        (grounding._flat(item.get("holder") or ""),
         grounding._flat(item.get("method") or ""))
        for item in aggregates.get("decisions") or []
        if isinstance(item, dict) and item.get("include_empty_groups") is not None
    }
    report["ambiguous_aggregate_groups"] = [
        item for item in report.get("ambiguous_aggregate_groups") or []
        if (grounding._flat(item.get("holder") or ""),
            grounding._flat(item.get("method") or "")) not in aggregate_keys
    ]
    report["applied_decisions"] = {
        "drop_services": sorted({grounding._flat(name) for name in
                                 decisions.get("drop_services") or []}),
        "drop_methods": sorted(
            ".".join((grounding._flat(item.get("holder") or ""),
                      grounding._flat(item.get("method") or "")))
            for item in decisions.get("drop_methods") or []
            if isinstance(item, dict)),
        "aggregate_groups": sorted(".".join(item) for item in aggregate_keys),
    }
    return report, requirements, services


def _aggregate_parent(out_dir, method, models):
    flat = grounding._flat(method)
    for model in models or []:
        name = model.get("name") if isinstance(model, dict) else None
        if not isinstance(name, str) or grounding._flat(name) not in flat:
            continue
        primary = next((field.get("name") for field in model.get("fields") or []
                        if isinstance(field, dict) and field.get("primary_key")),
                       None)
        if isinstance(primary, str):
            return name, primary
    return None, None


def _merge_decision(path, payload):
    existing = _read(path, {})
    if not isinstance(existing, dict):
        existing = {}
    for key, value in payload.items():
        if isinstance(value, list):
            previous = existing.get(key) or []
            existing[key] = sorted({json.dumps(item, sort_keys=True)
                                    for item in [*previous, *value]})
            existing[key] = [json.loads(item) for item in existing[key]]
        else:
            existing[key] = value
    with open(path, "w", encoding="utf-8") as handle:
        handle.write(json.dumps(existing, indent=2, ensure_ascii=False) + "\n")


def collect_questions(out_dir):
    """Questions the attended grounding review would ask."""
    report, _requirements, _services = _build_report(out_dir)
    if report is None:
        return []
    questions = []
    extras = report.get("extra_methods") or []
    by_holder = {}
    for item in extras:
        by_holder.setdefault(item["holder"], []).append(item["method"])
    for holder, methods in by_holder.items():
