#!/usr/bin/env python3
"""Generate a bounded slice of the final3 projects."""
from __future__ import annotations
import argparse, json, subprocess, sys, time
from pathlib import Path

ROOT=Path('/Users/gillesstenger/Documents/Projets SFEIR/esus')
RUN=ROOT/'out/validation/runs/mac-final3-20261125'

def main():
    ap=argparse.ArgumentParser(); ap.add_argument('--start',type=int,default=0); ap.add_argument('--count',type=int,default=20); a=ap.parse_args()
    projects=sorted(p for p in RUN.glob('prompt_*') if p.is_dir())
    chunk=projects[a.start:a.start+a.count]
    failures=[]; seconds=0.0; tokens={'calls':0,'tokens_out':0,'tokens_prompt':0,'decode_seconds':0.0}
    for project in chunk:
        t=time.monotonic()
        r=subprocess.run([sys.executable,'generator.py',str(project),'--model','server','--reuse-reviewed-bodies'],cwd=ROOT,capture_output=True,text=True)
        dt=time.monotonic()-t; seconds+=dt
        (project/'generate_stage.out').write_text(f"$ generator.py {project}\n\n{r.stdout}\n\n{r.stderr}\n",encoding='utf-8')
        combined=r.stdout+'\n'+r.stderr
        if r.returncode or 'refusing:' in combined.lower():
            failures.append({'project':project.name,'exit':r.returncode,'tail':combined[-3000:]})
        apath=project/'llm_stub_answers.json'
        if apath.is_file():
            try: rows=json.loads(apath.read_text())
            except ValueError: rows=[]
            for row in rows:
                tokens['calls']+=1; tokens['tokens_out']+=int(row.get('tokens') or 0); tokens['tokens_prompt']+=int(row.get('prompt_tokens') or 0); tokens['decode_seconds']+=float(row.get('decode_seconds') or 0)
        print(f'{project.name}: {"FAILED" if failures and failures[-1]["project"]==project.name else "ok"} {dt:.1f}s',flush=True)
    payload={'start':a.start,'count':len(chunk),'seconds':round(seconds,3),'tokens':tokens,'failures':failures}
    (RUN/f'generation_stage_{a.start}.json').write_text(json.dumps(payload,indent=2)+'\n',encoding='utf-8')
    if failures: raise SystemExit('generation failed')
    return 0

if __name__=='__main__': raise SystemExit(main())

