"""Classify oracle outcomes into code findings, case defects and gaps."""

from __future__ import annotations


def classify(status, reason, source=None):
    text = str(reason or "").lower()
    requirement = str(source or "").lower()
    if status == "passed":
        return "passed"
    if status == "unbound":
        if "ambiguous action binding" in text:
            return "coverage_gap: ambiguous action"
        if ("expected state" in text
                or "primary-key" in text
                or "cannot resolve given entity" in text
                or "is not an entity named" in text
                or "is not a mapping" in text
                or "setup needs" in text):
            return "case_defect: setup"
        if "no generated method" in text or "no generated cli path" in text:
            return "coverage_gap: missing action"
        if any(marker in text for marker in (
                "supplies no new value", "supplies no value for required field",
                "passes parameter name", "list case expects fewer rows",
                "supplies unknown argument")):
            return "case_defect: setup"
        return "coverage_gap: other"
    if status != "failed":
        return f"{status}: other"
    if ("cannot read" in text
            and "soft delete" in requirement
            and any(word in requirement for word in
                    ("remains in the database", "still exists", "not removed"))):
        return "behavior: soft delete"
    if ("is datetime.datetime" in text and "expected '" in text) \
            or "datatype mismatch" in text \
            or (".id is " in text and "expected 1" in text):
        return "case_defect: setup"
    if any(word in text for word in (
            "matched 0 records", "matched no records", "notfounderror",
            "not found", "already exists", "unknown scenario reference",
            "keyerror", "takes from", "unexpected keyword",
            "integrityerror", "not null constraint")):
        return "case_defect: setup"
    if "row count is" in text:
        return "behavior: row count"
    if "is " in text and ", expected " in text:
        return "behavior: state value"
    if "expected" in text and "no error was raised" in text:
        return "behavior: expected error missing"
    if text.startswith("raised ") and "expected" in text:
        return "behavior: wrong error"
    return "behavior: other"
"""Align verifier concepts with extracted documents without changing outcomes.

The verifier may call a concept `Client` while the extracted model calls it
`Customer`, or `PurchaseOrder` while the prompt says `order`. Treating every
such difference as a verifier hallucination or an extraction defect is wrong.
This module classifies the difference before binding:

- aligned       exact concept;
- alias         same concept, different spelling;
- ambiguous     several plausible concepts;
- coverage_gap  prompt names it, no extracted candidate;
- invented      no prompt evidence and no extracted candidate;
- under_specified prompt cannot decide what the concept means.

Only names and setup structure are aligned here. Expected outcomes are never
taken from the extracted documents.
"""

from __future__ import annotations

from dataclasses import dataclass, field
import re

from kernel import codegen
from kernel.consistency.naming import normalize

_GENERIC = frozenset({
    "entity", "record", "row", "item", "thing", "object", "data", "value",
    "number", "result", "response", "file", "input", "output",
})

_FIELD_ALIASES = {
    "phone": ("phone_number", "phonenumber"),
    "phonenumber": ("phone",),
    "stockquantity": ("stock_qty", "quantity"),
    "stockqty": ("stock_quantity", "quantity"),
    "quantity": ("qty", "stock_quantity", "stock_qty"),
    "name": ("title", "description"),
    "title": ("name", "description"),
    "sku": ("code", "product_code"),
    "maxcapacity": ("maximum_capacity",),
    "maximumcapacity": ("max_capacity",),
    "totalstock": ("stock_quantity",),
}


@dataclass
class Alignment:
    status: str
    canonical: str | None
    score: float
    evidence: list[str] = field(default_factory=list)
    alternatives: list[str] = field(default_factory=list)


def _models(docs):
    return [model for model in docs.get("models") or []
            if isinstance(model, dict) and model.get("name")]


def _fields(model):
    return [field.get("name") for field in model.get("fields") or []
            if isinstance(field, dict) and field.get("name")]


def _field_set(model):
    return {normalize(name) for name in _fields(model)}


def _singular(value):
    value = normalize(value)
    if value.endswith("ies") and len(value) > 4:
        return value[:-3] + "y"
    if value.endswith("s") and not value.endswith("ss") and len(value) > 3:
        return value[:-1]
    return value


def _tokens(value):
    text = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", str(value or ""))
        return False
    first = normalize(params[0])
    if isinstance(args, dict):
        return any(normalize(key) in ("id", first) for key in args)
    values = args if isinstance(args, list) else [args]
    if not values:
        return False
    for value in values:
        if isinstance(value, dict) and isinstance(value.get("ref"), str)                 and value["ref"].split(".")[-1] in ("id", first):
            return True
        if isinstance(value, str) and "." in value                 and value.split(".")[-1] in ("id", first):
            return True
    if first in ("id", "key") or first.endswith("id"):
        return isinstance(values[0], (int, float)) or (
            isinstance(values[0], str) and values[0].isdigit())
    return False


def _coerce_value(value, declared):
    if not isinstance(value, str) or value.startswith("{"):
        return value
    kind = str(declared or "").lower()
    if any(token in kind for token in ("int", "integer")):
        try:
            return int(value)
        except ValueError:
            return value
    if kind in ("float", "double", "decimal", "money", "number"):
        try:
            return float(value)
        except ValueError:
            return value
    if kind in ("bool", "boolean"):
        if value.strip().lower() in ("true", "false"):
            return value.strip().lower() == "true"
    return value


def _coerce_args(method, args):
    """Literal CLI values are strings in cases; generated methods are typed."""
    params = [param for param in method.get("params") or []
              if isinstance(param, dict) and param.get("name")]
    by_name = {normalize(param["name"]): param.get("type") for param in params}
    if isinstance(args, dict):
        return {key: _coerce_value(value, by_name.get(normalize(key)))
                for key, value in args.items()}
    if isinstance(args, list):
        return [_coerce_value(value,
                              params[index].get("type")
                              if index < len(params) else None)
                for index, value in enumerate(args)]
    return args


def _has_soft_delete(model, requirements):
    text = str(requirements or "").lower()
    if "soft delete" not in text and "soft-delete" not in text:
        return False
    fields = {normalize(field.get("name")): field for field in model.get("fields") or []
              if isinstance(field, dict) and field.get("name")}
    return any(name in fields and str(fields[name].get("type") or "").lower()
               in ("bool", "boolean")
               for name in ("isdeleted", "deleted", "isarchived", "archived"))


def _delete_state_error(case, docs, setup, method, requirements):
    if codegen.classify_crud(method.get("name") or "") != "delete":
        return None
    state = (case.get("then") or {}).get("state")
    if not isinstance(state, dict) or not state:
        return None
    by_alias = {normalize(step.get("as") or ""): step for step in setup}
    for target in state:
        alias, _, _field = str(target).partition(".")
        step = by_alias.get(normalize(alias))
        if step is None:
            continue
        model = next((item for item in docs.get("models") or []
                      if isinstance(item, dict)
                      and item.get("name") == step.get("entity")), None)
        if model is None or _has_soft_delete(model, requirements):
            continue
        return (f"delete case expects state on deleted {model.get('name')}; "
                "a hard-deleted row has no state to read")
    return None


def _complete_id_args(method, args, setup):
    """Fill `<entity>_id` parameters from the matching seeded aliases."""
    aliases = {normalize(step.get("as") or ""): step for step in setup}
    kwargs = {}
    for param in method.get("params") or []:
        if not isinstance(param, dict) or not param.get("name"):
            continue
        name = normalize(param["name"])
        if name == "id":
            candidates = [step for step in setup if step.get("seed") is not False] \
                or list(setup)
            if len(candidates) == 1:
                kwargs[param["name"]] = {"ref": f"{candidates[0].get('as')}.id"}
            continue
        if not name.endswith("id"):
            continue
        base = name[:-2]
        step = aliases.get(base)
        if step is not None:
            kwargs[param["name"]] = {"ref": f"{step.get('as')}.id"}
    if not kwargs:
        return args
    if isinstance(args, dict):
        kwargs.update(args)
        return kwargs
    # If the method only needs IDs, ignore the case's noisy positional values.
    ids = [param for param in method.get("params") or []
           if isinstance(param, dict) and normalize(param.get("name") or "").endswith("id")]
    non_ids = [param for param in method.get("params") or []
               if isinstance(param, dict) and not normalize(param.get("name") or "").endswith("id")]
    if not non_ids and len(kwargs) == len(ids):
        return kwargs
    # `list_books` may say `["author"]`; the method expects `author_id`.
    # A bare alias is a row reference, so use the FK when the method has one.
    bare = [value for value in args if isinstance(value, dict)
            and isinstance(value.get("ref"), str)
            and "." not in value["ref"]]
    if kwargs and bare and len(bare) == len(args):
        return kwargs
    if kwargs and codegen.classify_crud(method.get("name") or "") == "delete":
        # A delete is identified by its primary key. Remaining positional
        # values are lookup data, not fields to write.
        return kwargs
    return args


def _scalar(text):
    """A named case value as the scalar it spells, not always a string."""
    if not isinstance(text, str):
        return text
    lowered = text.strip().lower()
    if lowered in ("true", "false"):
        return lowered == "true"
    if lowered in ("none", "null"):
        return None
    try:
        return int(text)
    except (TypeError, ValueError):
        try:
            return float(text)
        except (TypeError, ValueError):
            return text


def _param_keys(params):
    """Map canonical and common field aliases to a method parameter name."""
    keys = {normalize(name): name for name in params}
    for alias, targets in _FIELD_ALIASES.items():
        target_names = {normalize(target) for target in targets}
        for name in params:
            if normalize(name) in target_names:
                keys.setdefault(alias, name)
    return keys

